import React from 'react';
import { LogInfoIcon } from '../../IconSvg';
import { NoLogIcon, NoLogsContainerWrapper } from '../styles/AppLogStyles';
import LogEmptyInfo from './LogEmptyInfo';
import LogNonEnabled from './LogNonEnabled';
import LogNotRecorded from './LogNotRecorded';

const Icon = '/static/loginfo.svg';

const AppLogInfo = ({ isAppLogValid, isAppLogRecorded, platform }) => (
  <NoLogsContainerWrapper>
    <NoLogIcon src={Icon} alt="no log info" />
    <LogInfoIcon />
    {!isAppLogValid ? (
      <LogEmptyInfo platform={platform} />
    ) : !isAppLogRecorded ? (
      <LogNotRecorded />
    ) : (
      <LogNonEnabled />
    )}
  </NoLogsContainerWrapper>
);

export default AppLogInfo;
