export const MenuItemGroup = Menu.ItemGroup;
export const MenuItem = Menu.Item;
const DropdownHeaderStyled = styled.div`
  .ant-input {
    margin-bottom: 5px;
    border-radius: 4px;
  }
`

const ButtonsPillWrapper = styled.div`
  display: flex;
  width: 100%;
  gap: 10px;
  margin-bottom: 10px;
  button {
    font-weight: 400;
    width: 50%;
    display: flex;
    justify-content: center;
    border-radius: 30px;
    line-height: 16px;
  }
`

const IconWrapper = styled.div`
  width: 20px;
  height: 13px;
  overflow: hidden;

  .custom-icon {
    height: 13px;
    fill: #090F19;
  }
`

const EventGestureTimelineDropdown = ({
  uploadedOn,
}) => {
  const {
      sessionDetailReducer: sessionDetail,
      screenTimelineReducer: screenFilteredData,
      urlReducer: urlQuery
  } = useSelector((state) => state);
  const {
    selectedEventField,
    selectedGestureField,
    allEvents,
    isEventTriggered,
  } = screenFilteredData;
  const inputRef = useRef();
  const dispatch = useDispatch();
  const [searchValue, setSearchValue] = useState('');
  const [eventList, setEventList] = useState([]);
  const [nocodeEventList, setNocodeEventList] = useState([]);
  const [gestureList, setGestureList] = useState([]);
  const [eventVisible, setEventVisible] = useState(false);
  const [gestureVisible, setGestureVisible] = useState(false);
  const [toggleEvent, setToogleEvent] = useState(allEvents);
  const [tempSelectedEvents, setTempSelectedEvents] = useState( [] );
  const [tempSelectedGestures, setTempSelectedGestures] = useState( [] );
  const [nocodeEventsTabActive, setNocodeEventsTabActive] = useState( false );

  // @TODO - remove this once backend fixes attribute name
  const nocodeEventListFixed = useMemo( () => nocodeEventList.map( (event) => ( { name: event.event_name, count: event.count, isSmartEvent: true } ) ), [ nocodeEventList ] )
  const combinedEvents = useMemo( () => [ ...nocodeEventListFixed, ...eventList ], [ nocodeEventListFixed, eventList ] );
  const dataList = useMemo( () => nocodeEventsTabActive ? nocodeEventListFixed : eventList, [ nocodeEventsTabActive, eventList, nocodeEventListFixed ] )
  const timerRef = useRef()

  const { sessionid, secondarysessionid, appId, parentType } = urlQuery;
  const {
    setSessionGestures,
    setSessionEvents,
    setSessionNocodeEvents,
    sessionGestures: sharedSessionGestures,
  } = useSessionTimeLine();
  
  const sessionId =  parentType === 'aiSessionsList' ? secondarysessionid : sessionid
  const reqBody = useMemo(
    () => ({
      appid: appId,
      sessionid: sessionId,
      uploadedon: uploadedOn
    }),
    [appId, sessionId, uploadedOn]
  );

  const isSharedSession = useMemo(() => urlQuery?.parentType === 'shareSession', [urlQuery]);

  const { data: sessionGestures, refetch: refetchGestures, isLoading: loadingGestures } =
    useSessionGestures(reqBody, !isSharedSession);
  const { data: sessionEvents, isLoading: loadingEvents } =
    useSessionEvents(reqBody, eventVisible && !isSharedSession);
  const { data: sessionNocodeEvents, isLoading: loadingNocodeEvents } =
    useSessionNocodeEvents(reqBody, eventVisible && nocodeEventsTabActive && !isSharedSession);

    const shareKey = urlQuery.shareSessionKey;

    const {
      data: sharedSessionEventsResponse,
      isLoading: loadingSharedEvents,
    } = useShareSessionData(
      'event-details',
      '/sessions/get-event-details/',
      shareKey,
      eventVisible && isSharedSession
    );
    const sharedSessionEvents = useMemo(() => sharedSessionEventsResponse?.data?.data || [], [sharedSessionEventsResponse]);

    const { data: nocodeEventsData, isLoading: loadingSharedNocodeEvents } =
      useSharedDetailsNocodeEvents(
        shareKey,
        eventVisible && nocodeEventsTabActive && isSharedSession
      );
    const sharedSessionNocodeEvents = useMemo(() => nocodeEventsData?.data?.data || [], [nocodeEventsData]);

    const gestureCount = sessionGestures?.length || 0;
  const sessionDetailLoader = sessionDetail?.loader;

  useEffect(() => {
    if (sessionGestures && !isSharedSession) {
      setGestureList(sessionGestures?.data?.data || []);
      setSessionGestures(sessionGestures?.data?.data || []);
    }
  }, [sessionGestures, setSessionGestures, isSharedSession]);

  useEffect(() => {
    if (sessionEvents && !isSharedSession) {
      setEventList(sessionEvents?.data?.data || []);
      setSessionEvents(sessionEvents?.data?.data || []);
    }
    return () => {
      setSessionEvents([]);
    };
  }, [sessionEvents, setSessionEvents, isSharedSession]);

  useEffect(() => {
    if (sessionNocodeEvents && !isSharedSession) {
      setNocodeEventList(sessionNocodeEvents?.data?.data || []);
      setSessionNocodeEvents(sessionNocodeEvents?.data?.data || []);
    }
    return () => {
      setSessionNocodeEvents([]);
    };
  }, [sessionNocodeEvents, setSessionNocodeEvents, isSharedSession]);

  //* FOR SHARED SESSIONS
 useEffect(() => {
   if (isSharedSession && sharedSessionGestures) {
     setGestureList(sharedSessionGestures);
   }
 }, [isSharedSession, sharedSessionGestures]);

 useEffect(() => {
   if (
     isSharedSession &&
     sharedSessionEvents &&
     sharedSessionEvents.length > 0
   ) {
     setEventList(sharedSessionEvents);
   }
 }, [isSharedSession, sharedSessionEvents]);

 useEffect(() => {
   if (isSharedSession && sharedSessionNocodeEvents) {
     setNocodeEventList(sharedSessionNocodeEvents);
   }
 }, [isSharedSession, sharedSessionNocodeEvents]);

  useEffect(() => {
    // NOTE: CX-1635
    if (!isSharedSession && sessionId) {
      refetchGestures();
    }
    // refetchEvents();
    // refetchNocodeEvents();
  }, [sessionId]);

  const getListItems = useCallback( (list) => toggleEvent ? list : list.filter((item) => item.count !== 0), [ toggleEvent ]);
  const menuList = useMemo( () => eventVisible ? getListItems(dataList) : gestureList, [ eventVisible, dataList, gestureList, getListItems ] )
  const menuListFiltered = useMemo( () => menuList.filter(x => x.name.toLowerCase().includes(searchValue)), [ menuList, searchValue ] )
  const checkedList = useMemo( () => eventVisible ? tempSelectedEvents : tempSelectedGestures, [ eventVisible, tempSelectedEvents, tempSelectedGestures ] )

  const doContainFieldName = useCallback( (fields, name) => fields.some((field) => field.name === name), [] );

  const handleMenuClick = useCallback( (e, { name, count, isSmartEvent }, selectedValue) => {
    e.preventDefault()
    if (selectedValue === 'events') {
      const containEvent = tempSelectedEvents.map(v => v.name).indexOf(name) > -1
      if (containEvent) {
        setTempSelectedEvents(tempSelectedEvents.filter((value) => value.name !== name));
      } else {
        setTempSelectedEvents([...tempSelectedEvents, { name, count, isSmartEvent }]);
      }
    }
    if (selectedValue === 'gestures') {
      const containGesture = tempSelectedGestures.map(v => v.name).indexOf(name) > -1
      if (containGesture) {
        setTempSelectedGestures(tempSelectedGestures.filter((value) => value.name !== name));
      } else {
        setTempSelectedGestures([...tempSelectedGestures, { name, count }]);
      }
    }
    dispatch(setSessionEventTriggered(true));
  }, [ dispatch, tempSelectedEvents, tempSelectedGestures ] );

  const handleSearch = (e) => setSearchValue(e.target.value.trim().toLowerCase());

  const handleToggle = useCallback( (flag) => {
    setToogleEvent(flag);
    dispatch(setAllEvents(flag));
  }, [ dispatch ]);

  const handleEventVisibleChange = useCallback( (flag) => {
    setEventVisible(flag);
    setSearchValue('');
  }, []);

  const handleGestureVisibleChange = useCallback( (flag) => {
    setGestureVisible(flag);
    setSearchValue('');
  }, [] );

  const handleReset = useCallback( ( type ) => {
    if ( type === 'events' ) {
      dispatch( setScreenTimeLineEvents( combinedEvents ) )
      handleEventVisibleChange( false )
    } else {
      dispatch(setScreenTimeLineGestures( gestureList ) )
      handleGestureVisibleChange( false )
    }
    setSearchValue( '' )
  }, [ combinedEvents, gestureList, dispatch, handleEventVisibleChange, handleGestureVisibleChange ] )

  const handleApply = useCallback( () => {
    if ( eventVisible ) {
        dispatch(setScreenTimeLineEvents( tempSelectedEvents ) )
        dispatch(trackPageViews(null, {
          eventName: 'filter_events',
          track_type: 'event',
          pageName: urlQuery?.parentType,
          eventProperty: {
            ...(urlQuery?.parentType === 'heatmapsList' && { screenname: urlQuery?.screenname }),
            ...(urlQuery?.parentType === 'heatmapsList' && { sessionid: sessionId }),
          }
        } ) )
      handleEventVisibleChange( false )
    } else {
      dispatch(setScreenTimeLineGestures( tempSelectedGestures ));
      dispatch(trackPageViews(null, {
        eventName: 'filter_gestures',
        track_type: 'event',
        pageName: urlQuery?.parentType,
        eventProperty: {
          gestures: tempSelectedGestures,
          ...(urlQuery?.parentType === 'heatmapsList' && { screenname: urlQuery?.screenname }),
          ...(urlQuery?.parentType === 'heatmapsList' && { sessionid: sessionId }),
        }
      } ) )
      handleGestureVisibleChange( false )
    }
  }, [ tempSelectedEvents, dispatch, eventVisible, sessionId, menuListFiltered, sessionNocodeEvents, urlQuery, tempSelectedGestures, searchValue, nocodeEventsTabActive, sessionEvents, handleEventVisibleChange, handleGestureVisibleChange ] )

  const handleClickCodedEvents = useCallback( () => setNocodeEventsTabActive( false ), [] )
  const handleClickNoCodeEvents = useCallback( () => setNocodeEventsTabActive( true ), [] )

  // This is version when we have search results clear all will afect only the search results
  const handleClearAllOptions = useCallback( ( type ) => {
    if ( type === 'events' ) {
      if ( searchValue?.length ) {
        const newData = tempSelectedEvents.filter( event => !menuListFiltered.some( menuEvent => menuEvent.name === event.name ) )
        setTempSelectedEvents( newData )
      } else {
        nocodeEventsTabActive ?
          setTempSelectedEvents( tempSelectedEvents.filter( 
            event => !nocodeEventListFixed.some( nocodeEvent => nocodeEvent.name === event.name ) 
          ) ) 
        : setTempSelectedEvents( tempSelectedEvents.filter( 
          event => !eventList.some( eventListItem => eventListItem.name === event.name ) 
        ) ) 
      }
    } else {
      setTempSelectedGestures( [] )
    }
  }, [ eventList, nocodeEventListFixed, menuListFiltered, searchValue, nocodeEventsTabActive, tempSelectedEvents ] )

  const handleSelectAll = useCallback( ( type ) => {
    if ( type === 'events' ) {
      if ( searchValue?.length ) {
        if ( nocodeEventsTabActive ) {
          const tempSelectedEventsWithoutNoCode = tempSelectedEvents.filter(
            event => !nocodeEventListFixed.some( nocodeEvent => nocodeEvent.name === event.name )
          )
          const newData = [ ...tempSelectedEventsWithoutNoCode, ...menuListFiltered ]
          setTempSelectedEvents( newData )
        } else {
          const tempSelectedEventsWithoutCoded = tempSelectedEvents.filter(
            event => !eventList.some( eventListItem => eventListItem.name === event.name )
          )
          setTempSelectedEvents( [ ...tempSelectedEventsWithoutCoded, ...menuListFiltered ] )
        }
      }else {
        const eventsToAdd = nocodeEventsTabActive ? nocodeEventListFixed : eventList
        const newEvents = [ ...new Set( [ ...tempSelectedEvents, ...eventsToAdd ] ) ]
        setTempSelectedEvents( newEvents )
      }
    } else {
      setTempSelectedGestures( gestureList )
    }
  }, [searchValue, nocodeEventsTabActive, menuListFiltered, nocodeEventListFixed, eventList, tempSelectedEvents, gestureList] )

  const selectAllDisabled = useMemo( () => sessionDetailLoader || menuList.every( menuItem => checkedList.some( item => item.name === menuItem.name && item.count === menuItem.count ) ), [ checkedList, menuList, sessionDetailLoader ] )
  const clearAllDisabled = useMemo( () => sessionDetailLoader || menuList.every( menuItem => !checkedList.some(item => item.name === menuItem.name && item.count === menuItem.count) ), [ checkedList, menuList, sessionDetailLoader ] )

  const overlay = useCallback( (type) => (
      <Menu>
        <DropdownHeaderStyled>
          { type === 'events' && (
            <ButtonsEventToggleWrapper toggleEvent={ toggleEvent }>
              <Button onClick={() => handleToggle(true)}>
                All events
              </Button>
              <Button onClick={() => handleToggle(false)}>
                In this session
              </Button>
            </ButtonsEventToggleWrapper>
          ) }
          { type === 'events' && (
            <ButtonsPillWrapper>
              <ButtonNew variant={ nocodeEventsTabActive ? 'secondary' : 'primary' } onClick={ handleClickCodedEvents }>
                Coded events
              </ButtonNew>
              <ButtonNew variant={ nocodeEventsTabActive ? 'primary' : 'secondary' } onClick={ handleClickNoCodeEvents }>
                Smart events
              </ButtonNew>
            </ButtonsPillWrapper>
          ) }
          {type === 'events' && (
            <SearchWrapper>
              <DebounceInputStyled
                value={searchValue}
                placeholder="Search events"
                debounceTimeout={500}
                inputRef={inputRef}
                onChange={handleSearch}
              />
              <IconSearch />
            </SearchWrapper>
          )}
          <SelectAllAndClearWrapper>
            <SelectAllAndClear
              handleSelectAllOptions={ () => handleSelectAll( type ) }
              handleClearAllOptions={ () => handleClearAllOptions( type ) }
              disableSelect={ selectAllDisabled }
              disableClear={ clearAllDisabled }
            />
          </SelectAllAndClearWrapper>
        </DropdownHeaderStyled>
        <MenuItemGroup className="menu-item-group">
          {menuListFiltered.length ? (
            menuListFiltered.map((item) =>
              <Menu.Item
                className={item.count === 0 ? 'timeline-options timeline-event-none' : 'timeline-options'}
                key={item.name + item.count}
              >
                <Checkbox
                  className="check-option"
                  checked={checkedList.map(v => v.name).includes(item.name)}
                  onChange={(e) => handleMenuClick(e, item, type)}
                  value={item.name}
                  key={item.name}
                >
                  <div className="check-option-title" >
                      {type === 'gestures' && (
                        <IconWrapper>
                          <GesturePack name={item.name} />
                        </IconWrapper>
                      )}{' '}
                    <span className="check-option-name">
                      {item.name}
                    </span>
                    <span className="check-option-count">{item.count}</span>
                  </div>
                </Checkbox>
              </Menu.Item>
            )
          ) : (
            <div className="no-event-message">
              {
                loadingEvents || loadingNocodeEvents || loadingSharedEvents || loadingSharedNocodeEvents ? `loading ${type}...` : `No ${type} in this session`
              }
            </div>
          )}
        </MenuItemGroup>
        <ButtonsBottom>
          <ButtonNew 
            onClick={ () => handleReset( type ) }
            variant='ghost'
          >
            Reset
          </ButtonNew>
          <ButtonNew
            onClick={ () => handleApply(type) }
            variant='primary'
          >
            Apply
          </ButtonNew>
        </ButtonsBottom>
      </Menu>
    ), [ checkedList, menuListFiltered, searchValue, toggleEvent, nocodeEventsTabActive, clearAllDisabled, selectAllDisabled, handleApply, handleMenuClick, handleReset, handleToggle, handleClearAllOptions, handleSelectAll, handleClickCodedEvents, handleClickNoCodeEvents 
        ,loadingEvents, loadingNocodeEvents, loadingSharedEvents, loadingSharedNocodeEvents
    ])

  const getCheckedCount = useCallback( (type) => {
    let count = 0;
    const actualList = type === 'events' ? combinedEvents : gestureList;
    const selectedList = type === 'events' ? selectedEventField : selectedGestureField;
    actualList?.forEach((al) => {
      if (doContainFieldName(selectedList, al.name)) {
        count += 1;
      }
    });
    return count;
  }, [ selectedGestureField, combinedEvents, gestureList, selectedEventField, doContainFieldName ] );

  useEffect(() => {
    if (sessionEvents && sessionGestures && sessionNocodeEvents) {
      setEventList(sessionEvents?.data.data);
      setNocodeEventList(sessionNocodeEvents?.data.data);
      setGestureList(sessionGestures?.data.data);
    }
  }, [sessionId, toggleEvent, sessionEvents, sessionGestures, sessionNocodeEvents]);

  useEffect(() => {
    if (dataList?.length ) {
      timerRef.current = setTimeout( () => {
        dispatch(
          setScreenTimeLineEvents(
            !isEventTriggered
              ? combinedEvents
              : selectedEventField
          )
        )
      }, 1000 )
    }
    return () => {
      setScreenTimeLineEvents([]);
      clearTimeout(timerRef.current)
    }
  }, [ dispatch, dataList ]);

  useEffect(() => {
    if (!gestureList.length) return;
    dispatch(
      setScreenTimeLineGestures(
        !isEventTriggered && selectedGestureField.length === 0
          ? gestureList
          : selectedGestureField
      )
    );
  }, [gestureList, sessionGestures, dispatch, isEventTriggered, selectedGestureField]);

  useEffect(() => {
    if (inputRef.current && eventVisible) {
      setTimeout(() => {
        inputRef.current.focus();
      }, 1000);
    }
  }, [eventVisible, toggleEvent]);

  useEffect( () => selectedEventField && setTempSelectedEvents( selectedEventField ), [ selectedEventField ])
  useEffect( () => selectedGestureField && setTempSelectedGestures( selectedGestureField ), [ selectedGestureField ])
  useEffect( () => setSearchValue( '' ), [ nocodeEventsTabActive ] )

  return (
    <>
      <GlobalStyles />
      <Dropdown
        visible={eventVisible}
        trigger={['click']}
        disabled={sessionDetailLoader}
        onVisibleChange={handleEventVisibleChange}
        overlay={overlay('events')}
        overlayClassName="screen-timeline-search-dropdown-restyled"
        getPopupContainer={getPopupContainer}
        placement='bottomLeft'
        align={ { offset: [ 0, 8 ] } }
      >
        <Tooltip title="Select events that should be shown on the timeline.">
          <Button className={ getCheckedCount('events') < combinedEvents?.length ? 'filter-applied' : '' } data-intercom-target="Events dropdown">
            <QuickFilterSVG /> Events{' '}
            {getCheckedCount('events') < combinedEvents?.length && (
              <Badge showZero count={getCheckedCount('events')} />
            )}
          </Button>
        </Tooltip>
      </Dropdown>
      <Dropdown
        disabled={sessionDetailLoader}
        visible={gestureVisible}
        trigger={['click']}
        onVisibleChange={handleGestureVisibleChange}
        overlay={overlay('gestures')}
        overlayClassName="screen-timeline-search-dropdown-restyled"
        getPopupContainer={getPopupContainer}
        placement='bottomCenter'
        align={ { offset: [ 0, 8 ] } }
      >
        <Tooltip title="Select gestures that should be shown on the timeline.">
          <Button loading={loadingGestures} className={ getCheckedCount('gesture') < gestureCount ? 'filter-applied' : '' } >
            <QuickFilterSVG /> Gestures{' '}
            {getCheckedCount('gesture') < gestureCount && (
              <Badge showZero count={getCheckedCount('gesture')} />
            )}
          </Button>
        </Tooltip>
      </Dropdown>
    </>
  )
}

export default memo( EventGestureTimelineDropdown )
