const InsightsTab = ({ isAISession }: IProps) => {
	const {
		currentAppReducer: { _id: appID },
		urlReducer: {
			sessionid: sessionID,
			secondarysessionid: secondarySessionID,
			parentType,
			shareSessionKey,
		 },
		screenRenamedList,
	} = useSelector((state: IReduxState) => state);
	const {
		rewind,
	}: {
		rewind: (seconds: number) => void;
	} = useSessionTimeLine();
	const dispatch = useDispatch()
	const { debugMode } = useAISidebarContext()

	// Check if this is a shared session
	const isSharedSession = parentType === 'shareSession';

	// For regular sessions
	const { data: regularData, isFetching: regularFetching } = useQuery({
		queryKey: ['ai-insights', appID, sessionID, secondarySessionID],
		queryFn: () =>
			getAIInsights({ appid: appID as string, sessionid: secondarySessionID || sessionID as string }),
		enabled: !isSharedSession && !!appID && (!!sessionID || !!secondarySessionID),
	});

	// For shared sessions
	const { data: sharedData, isFetching: sharedFetching } = useShareSessionAIInsights(
		shareSessionKey,
		isSharedSession && !!shareSessionKey
	);

	// Use the appropriate data based on session type
	const rawData = isSharedSession ? sharedData?.data?.data : regularData;
	const isFetching = isSharedSession ? sharedFetching : regularFetching;
	const data = rawData;

	const handleRewind = React.useCallback((timestamp: number, shortName: string, shortDescription: string) => {
		rewind(timestamp + 0.001)
		dispatch(
			trackPageViews(null, {
				eventName: 'wa_sessions_click_insights_timestamp',
				track_type: 'event',
				eventProperty: {
					time: timestamp,
					screen_name: shortName,
					screen_description: shortDescription,
				},
			})
		)
	}, [rewind, dispatch])

	if (!isAISession) {
		return (
			<NonAIContainer>
				<NoInsight />
				<Title>This session hasn’t been AI analyzed yet</Title>
				<SmallDescription>
					Tara works automatically, check back soon!
				</SmallDescription>
			</NonAIContainer>
		);
	}

	return (
		<Container>
			{isFetching ? (
				<Spinner data-size="m" />
			) : (
				<>
					{data?.user_friendly_description ? (
						<SessionDescriptionWrapper>
							<Markdown remarkPlugins={[remarkGfm]}>
								{data.user_friendly_description}
							</Markdown>
						</SessionDescriptionWrapper>
					) : (
						<>
							<TitleHeader>
								<Title>What happened in this session?</Title>
								{debugMode && data?.vision_version && (
									<VersionBadge>
										Vision {data.vision_version}
									</VersionBadge>
								)}
							</TitleHeader>
							<Description>
								{data?.description || 'No insights available for this session.'}
							</Description>
							<InfoBox>
								<span>Highlights:</span>
								{data?.highlight}
							</InfoBox>
						</>
					)}
					<Title>Screen summary:</Title>
					{data?.screens?.map(
						(screen: IScreenInsight) => {
							const { screen_name: shortName, short_description: shortDescription, timestamp_from: timestampFrom, timestamp_to: timestampTo } = screen
							const id =
								shortName + shortDescription + timestampFrom + timestampTo;
							const name = screenRenamedList[shortName || ''] || shortName
							return (
								<Screen key={id}>
									<ButtonWrapper onClick={() => handleRewind(timestampFrom, shortName, shortDescription)}>
										<PlayButton />
									</ButtonWrapper>
									<Time>
										{`${formatTime(timestampFrom)} - ${formatTime(
											timestampTo
										)}`}
									</Time>
									<ScreenText>
										<ScreenTitle>{name}</ScreenTitle>
										{shortDescription}
									</ScreenText>
								</Screen>
							);
						}
					)}
				</>
			)}
		</Container>
	);
};

export default InsightsTab;
