import React, {useEffect, useRef, useState, useMemo, useCallback} from 'react'
import {Button, Card, message, Popconfirm} from 'antd'
import {useDispatch, useSelector} from 'react-redux'
import {Mention, MentionsInput} from 'react-mentions'
import {useMutation, useQuery, useQueryClient} from "react-query";
import axios from "axios";

import {emailRegex, handleTimeFormat, timeFormatRegex, timeFormatToSecond} from 'Utils/helpers/commonUtils'
import {NoteDeleteSvg, NoteEditSvg} from 'components/svg_files'
import {axiosInstance}  from 'services/globalInstance'

let container

const SessionNoteList = (props) => {
    const [noteList, setNoteList] = useState([]);
    const [noteId, setNoteId] = useState();
    const [editedNote, setEditedNote] = useState();
    const [visibleEdit, setVisibleEdit] = useState(false);
    const [testValue, setTestValue] = useState([]);
    const [timeFormat, setTimeFormat] = useState([]);
    const queryClient = useQueryClient()
   const { users, redirectToVideo, defaultStyle, sessionDetail} = props;

    const noteInput = useRef(null);
    const listDivRef = useRef(null);
    const handleGetContainer = useCallback( () => listDivRef.current, [ listDivRef ] )

    const {profileReducer: profile,urlReducer} = useSelector(state => state);

    const {_id: sessionId, appId, time } = sessionDetail || {};
    const sessionUploadedDateTime = time?.sessionUploadedDateTime;
    const {sessionid, appId: appid, parentType } = urlReducer;
    const sessionIdCopy = sessionId || sessionid
    const appIdCopy = appId || appid
    const title = value => (<span className="title-name"><span className='name'>{`${value.userName} -`}</span> <span
        className="title-date">{handleTimeFormat(value.createdOn)}</span></span>);

    const {
        mutate: updateSessionNote,
    } = useMutation((body) => axiosInstance
            .post(`${process.env.PYTHON_API_URL}/notes/session/edit`, body,{
                withCredentials: true,
                credentials: 'include',
            }),
        { onSuccess: (data) => {
                setTimeFormat([]);
                data?.status === 422 && message.error(`${Object.values(data.data.error)}`)
                data?.status === 500 && message.error(`${Object.values(data.data.error)}`);
                return queryClient.invalidateQueries(['session-note', sessionId])
            },
        }

    );

    const handleUpdateNote = async (id) => {
        const isValidNote = editedNote.trim();
        if(isValidNote.length) {
            let content = editedNote
            users.map(user => {
                content = content.replaceAll(`[${user.display}](${user.id})`, `${user.email}`)
            });
            timeFormat && timeFormat.map(time =>{
                content = content.replaceAll(`@[${time}](abc)`, time)
            });
            const data = {note_id: id, updated_body: content, appid: appIdCopy, uploadedon: sessionUploadedDateTime};
            const updatedNote = noteList && noteList.map(value => value.noteId === id ? {
                ...value,
                body: data.updated_body
            } : value);
            setNoteList(updatedNote);
            setVisibleEdit(false);
            updateSessionNote(data)
        } else {
            setEditedNote(isValidNote)
        }
    };

    const scrollToBottom = () => {
        const noteListDiv = listDivRef?.current;
        if(noteListDiv) noteListDiv.scrollTop = noteListDiv?.scrollHeight;
    };

    const handleCancel = () => {
        setVisibleEdit(false);
    };

    const {
        mutate: deleteSessionNote,
    } = useMutation((body) => axiosInstance
            .delete(`${process.env.PYTHON_API_URL}/notes/session/delete/${body.appid}/${body.note_id}`, {
                withCredentials: true,
                credentials: 'include',
            }),
            {
          onSuccess: () => queryClient.invalidateQueries(['session-note', sessionId]),
          onMutate: () => {
                const sessionKey = parentType === 'aiSessionsList' ? 'aiSessionItems' : 'sessionItems'
                const sessionBodyKey = parentType === 'aiSessionsList' ? 'aiSessionsListReqBody' : 'sessionsListReqBody'
                let sessionBodyKeyVal = ''
                try {
                    sessionBodyKeyVal = JSON.parse(localStorage.getItem(sessionBodyKey))
                } catch (err) {
                    // silent fail
                }
                const sessionQueryKey = [sessionKey, sessionBodyKeyVal]
                queryClient.cancelQueries(sessionQueryKey);
                const previousValue = queryClient.getQueryData(sessionQueryKey);
                previousValue && queryClient.setQueryData(sessionQueryKey, (old) => {
                    const newBody = old.data.data.body.map((el) => {
                            if(el.sessionid === sessionId){
                                return {
                                    ...el,
                                    sessionNotesCount: Math.max(el.sessionNotesCount - 1, 0) }
                            }
                            return el
                        }
                    );
                    return {
                        ...old,
                        data: {
                            ...old.data,
                            data: {
                                ...old.data.data,
                                body: newBody,
                            },
                        },
                    };
                });
                return previousValue;
            }
        }
    );

    const confirmDelete = async (e, value) => {
        deleteSessionNote({note_id: value.noteId, appid: appIdCopy})
        setNoteList(noteList.filter(data => data.noteId !== value.noteId))
    };

    const handleChange = (e) => {
        let replaceValue = e.target.value
        timeFormat.length && timeFormat.map(time => {
            replaceValue = replaceValue.replaceAll(`@[${time}](abc)`, `${time}`)
        });
        const blocks =  replaceValue.split(' ')
        setTestValue([])
        const matchString = blocks.map(block => {
            let content  = block
            if (block.match(timeFormatRegex)) {
                const matchArray = block.match(timeFormatRegex)
                setTestValue(matchArray)
                for (let i = matchArray.length - 1; i >= 0; i--) {
                    content = content.replace(matchArray[i], `@[${matchArray[i]}](abc)`)
                }
                return content
            }
            return `${block}`;

        });
        const valueEvent =  matchString.join(' ')
        setEditedNote(valueEvent);
    };

    const highlightDisplayName = (value) => {
        let content = value;
        users.map(user => content = content.replaceAll(`@${user.email}`, `@[${user.display}](${user.id})`));
        return content
    };

    const highLightDisplayTime = (value) => {
        const blocks = value.split(" ");
        setTestValue([])
        const valueFormat = blocks.map(block => {
            let content = block
            if (block.match(timeFormatRegex)) {
                const matchArray = block.match(timeFormatRegex)
                setTestValue(matchArray)
                for (let i = matchArray.length - 1; i >= 0; i--) {
                    content = content.replaceAll(matchArray[i], `@[${matchArray[i]}](abc)`)
                }
                return content
            }
            return `${block}`;

        });
        return valueFormat.join(' ')
    }

    const handleEdit = async (value) => {
        await setNoteId(value.noteId);
        await setVisibleEdit(true);
        const noteBody = highlightDisplayName(value.body)
        const noteFormat = highLightDisplayTime(noteBody)
        await setEditedNote(noteFormat);
        noteInput && noteInput.current.focus();
    };

    const operations = (value) => (<div className="title-action">
        {profile.email === value.userEmail && <>
            <Button onClick={() => handleEdit(value)}>
                <NoteEditSvg/>
            </Button>
            <Popconfirm
                placement="topRight"
                trigger={['click']}
                title={<div className="note-delete-title"><p className="pop-title"><strong>Delete Note?</strong></p><p className="pop-des">This can’t be undone and the note will be deleted permanently.</p></div>}
                onConfirm={(e) => confirmDelete(e, value)}
                okText='Delete'
                cancelText='Cancel'
                icon=""
                overlayClassName="pop-up-session-note"
                getPopupContainer={handleGetContainer}
            ><Button>
                <NoteDeleteSvg/>
            </Button>
            </Popconfirm>
        </>
        }
    </div>);

    const handleNoteTimeClick = (e) => {
        const time = `${e.target.innerText}`;
        if(e.target.className === 'time-span-on-note'){
            redirectToVideo(timeFormatToSecond(time))
        }
    };

    const replaceEmailByUserName = (value) => {
        let content = value;
        users.map(user=> content = content.replaceAll(`@${user.email}`, `<span class='selected-user'>${user.display}</span>`));
        return(
            <span dangerouslySetInnerHTML={{
                __html: ` ${content} `
            }} />
        );
    };

    const handleNoteDisplay = (value) => {
        const blocks = value.split(" ");

        return blocks.map(block => {
            let content = block
            if (block.match(timeFormatRegex)) {
                const matchArray = block.match(timeFormatRegex)
                for (let i = matchArray.length - 1; i >= 0; i--) {
                    content = content.replace(matchArray[i], `<span class='time-span-on-note'}>${matchArray[i]}</span>`)
                }
                return(
                    <span aria-hidden = 'true' onClick={(e) => handleNoteTimeClick(e)} dangerouslySetInnerHTML={{
                        __html: ` ${content} `
                    }} />
                );
            } if(block.match(emailRegex)){
                return replaceEmailByUserName(block)
            }
            return ` ${block} `;

        });
    };

    const reqBody = useMemo(
        () => ({
            appid: appIdCopy,
            sessionid: sessionIdCopy,
            uploadedon: sessionUploadedDateTime
        }),
        [appId, sessionId, sessionUploadedDateTime]
    );

    const queryKey = useMemo(() => ['session-note', sessionId], [sessionId]);
    const { data: sessionNoteList } = useQuery(
        queryKey,
        () =>
            axios
                .post(`${process.env.PYTHON_API_URL}/notes/session/list`, reqBody, {
                    withCredentials: true,
                    credentials: 'include',
                })
                .then(({ data: { data } }) => data),
        {
        }
    );

    useEffect( ()=>{
        if(sessionNoteList){
            setNoteList(sessionNoteList)
        }
    },[sessionId, sessionNoteList])

    useEffect(() => scrollToBottom, [noteList, visibleEdit]);

    useEffect(() => {
        setVisibleEdit(false);
        setEditedNote()
        setTimeFormat([])
    }, [sessionDetail?.selectedTab]);

    useEffect(() => {
        if(testValue.length){
            const array3 = timeFormat.concat(testValue);
            setTimeFormat([...new Set(array3)])
        }
    }, [testValue]);

    return (
        <div ref={listDivRef} className="session-note-list">
            {noteList.length ? noteList.map((value) => (
                <div key={value.noteId} className="session-list-item" style={{marginTop: '10px'}}>
                    <Card size="small" title={title(value)} extra={operations(value)} bordered={false} key={value.noteId}>
                        {visibleEdit && value.noteId === noteId ?
                            <div className="edit-note" ref={el => {
                                container = el
                            }}>
                                <MentionsInput
                                    inputRef={noteInput}
                                    className={`mention-input ${!editedNote || editedNote?.length >= 1000 ? 'validation-message' : ''}`}
                                    value={editedNote}
                                    onChange={handleChange}
                                    maxLength={1000}
                                    style={defaultStyle}
                                    suggestionsPortalHost={container}
                                    forceSuggestionsAboveCursor
                                >
                                    <Mention
                                        trigger='@'
                                        data={users}
                                        appendSpaceOnAdd
                                        className='mention-inner-highlight'
                                    />
                                </MentionsInput>

                                <div className='button-wrapper'>
                                    <Button size="small" className="cancel-btn" onClick={handleCancel}>Cancel</Button>
                                    <Button size="small" disabled={!editedNote || editedNote?.length >= 1000}
                                            className="save-btn-title"
                                            onClick={() => handleUpdateNote(value.noteId)}>Save</Button>
                                </div>
                                {!editedNote ? <div className="has-error">Note can’t be empty.</div> : ''}
                                {editedNote && editedNote.length >= 1000 ?
                                    <div className="has-error">Reached max limit of 1000 characters.</div> : ''}
                            </div>
                            : <div key={value.noteId}>{handleNoteDisplay(value.body)}</div>
                        }
                    </Card>
                </div>
            )) : ''
            }
        </div>
    )
};

export default SessionNoteList
