/* eslint-disable @typescript-eslint/no-empty-function */
import React, { useMemo, useCallback, memo, useState, useEffect } from 'react';
import { Tooltip, message, Button } from 'antd';
import { CopyToClipboard } from 'react-copy-to-clipboard';
import styled from 'styled-components';
import { trackPageViews } from 'redux/actions/trackingReport';
import { QuestionCircleOutlined, CopyOutlined } from '@ant-design/icons';
import IconSession from 'public/static/icon-session-blue.svg';
import IconAnalyze from 'public/static/icon-analyze.svg';
import { useDispatch, useSelector } from 'react-redux';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import ButtonNew from 'components/common/ButtonNew';
import IconNocodeSettings from 'public/static/icon-no-code-settings.svg';
import { getActionType, getRageIcon } from 'Utils/helpers/SessionUtils';
import { isEmpty, isObject, map } from 'lodash';
import { theme } from 'theme';
import ScreenEventContent from './ScreenEventContent';
import { BottomWrapper, ContentWrapper } from './styles';
import { useSessionTimeLine, useSessionVideoControlls } from '../../Context';

export const TopButtonWrapper = styled.div`
  display: flex;
  gap: 16px;

  > button{
    flex-basis: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
  }
`

export const ManageEventWrapper = styled.div`
  width: 100%;
  margin-top: 20px;
  display: flex;
  flex-direction: column;

  >a {
    button{
    margin-top: 12px;
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  }
`
export interface IRule {
  activityName: string;
  idString: string;
  viewName: string;
  [key: string]: string;
}

interface StyledEventProps {
  obj: string;
  val: string;
  handleCopy?: (value: string) => string;
  copy?: (event: React.MouseEvent<HTMLElement>) => void;
  newSdk: boolean;
  smartRule?: IRule;
}

const AnyText = styled.span`
  font-style: italic;
  color: ${theme.colors.surface200.toString()};
  margin-left: 4px;
`;

const forOldSdk = ['viewName', 'viewType', 'idString'];

const changeKey = (key: string) => {
  if (key === 'viewName') {
    return 'UI element name';
  }
  if (key === 'viewType') {
    return 'UI element type';
  }
  if (key === 'idString') {
    return 'UI element ID';
  }
  if (key === 'viewClass') {
    return 'UI element class';
  }
  if (key === 'activityName') {
    return 'Screen name';
  }
  return key;
};

const StyledEventGesture = (props: StyledEventProps) => {
  const { obj, val, handleCopy, copy, newSdk, smartRule } = props;

  const anyText = useMemo(() => {
    if (
      smartRule &&
      Object.keys(smartRule).includes(obj) &&
      smartRule[obj] === '__any__'
    ) {
      switch (obj) {
        case 'idString':
          return '(includes all UI element id)';
        case 'viewName':
          return '(includes all UI element name)';
        case 'activityName':
          return '(includes all UI screen name)';
        default:
          return null;
      }
    }
    return null;
  }, [obj, smartRule]);

  const isUXCamOverload = useMemo(() => obj === '_UXCam_Overload', [obj]);
  const totalNumbers = useMemo(
    () => (isUXCamOverload ? val.match(/\d+/g) : []),
    [isUXCamOverload, val]
  );
  const emptyText = useMemo(() => (newSdk ? 'Undefined' : 'unknown'), [newSdk]);
  const newValue = useMemo(
    () =>
      isUXCamOverload
        ? `Too many properties in this event (${totalNumbers?.[0]} out of ${totalNumbers?.[1]}).`
        : val,
    [isUXCamOverload, totalNumbers, val]
  );

  const { isWebSession: isWebSdk } = useSessionTimeLine()

  const tooltipText = useMemo(() => {
    if(val === "Undefined" ||  emptyText === 'Undefined') {
      switch(obj){
        case 'viewName':
          return "UI element name couldn't be captured."
        case 'viewType':
          return "UI element type couldn't be captured."
        case 'idString':
          return "UI element id couldn't be captured."
        default:
          return null
      }
    }
    return !newSdk ? 'Please update your SDK to the latest version to capture the underlying UI components' : null
  
  },[emptyText, newSdk, obj, val]);

  if (['viewTypeId', 'gestureType', 'rule'].includes(obj)) {
    return null;
  }

  return (
    <div className="event-param-name" key={obj}>
      <div className="event-key-title">{changeKey(obj)}:</div>
      <div key={obj + val}>
        {newValue && newValue !== 'Undefined' ? (
          <>
            {newValue}
            {anyText && <AnyText>{anyText}</AnyText>}
            {copy && handleCopy && (
              <CopyToClipboard text={handleCopy(newValue)} onCopy={() => {}}>
                <Button
                  size="small"
                  icon={<CopyOutlined />}
                  onClick={(e) => copy(e)}
                />
              </CopyToClipboard>
            )}
          </>
        ) : (
          <>
            <i>{emptyText}</i>
            {anyText && <AnyText>{anyText}</AnyText>}
            {
              (tooltipText || emptyText) && !isWebSdk &&
              <Tooltip
                placement="topLeft"
                title={tooltipText}
              >
                <QuestionCircleOutlined />
              </Tooltip>
            }
          </>
        )}
      </div>
    </div>
  );
};

const EmptyProperties = ({
  newSdk,
  isEvent,
}: {
  newSdk: boolean;
  isEvent: boolean;
}) => {
  if (isEvent)
    return <p className="no-eventparam-message">No properties sent</p>;

  return (
    <>
      {map(forOldSdk, (obj) => (
        <StyledEventGesture obj={obj} val="Undefined" newSdk={newSdk} />
      ))}
    </>
  );
};

const GestureCollapseContent = ({
  action,
  newSdk,
  handleCreateEventBtn,
  displayAddEventBtn,
  screen,
  isEvent,
  eventName
}: any) => {
  const { properties, isRage, params } = action;
  const expandProperties = useMemo(
    () => properties || params,
    [properties, params]
  );
  const { currentAppReducer, urlReducer } = useSelector((state: any) => state);
  const { _id: appId, orgId } = currentAppReducer;
  
  const [smartRule, setSmartRules] = useState<IRule | undefined>(undefined);
  const { setShowDashboardTemplate, setCurrentAction, setCurrentScreen } =
    useNoCodeEventsContext();

  const { isSmartEvent, isScreenEvent } = getActionType(action);

  const constructedURL = useMemo(() => {
    const urlParam = {
      o: 'in',
      v: [eventName],
      tb: isSmartEvent ? 'no_code_event' : 'event',
    };
    const queryParams = `${isSmartEvent? 'nce_name' : 'event_name'}=${encodeURIComponent(JSON.stringify(urlParam))}`;
    const url = `/app/${appId}/sessions/list/1?${queryParams}`;

    return url;
  }, [appId, eventName, isSmartEvent])

  const handleWatchSessions = useCallback(() => {
    window.open(constructedURL, '_blank');
  }, [constructedURL]);


  useEffect(() => {
    if (expandProperties?.rule) {
      setSmartRules(expandProperties.rule);
    }
  }, [expandProperties?.rule]);


  const dispatch = useDispatch();

  const isSharedSession = useMemo(
    () => urlReducer?.parentType === 'shareSession',
    [urlReducer?.parentType]
  );

  const copy = async (e: React.MouseEvent<HTMLElement>) => {
    e.stopPropagation();
    e.preventDefault();
    message.success('copied');
  };
  const handleCopy = (value: string) => JSON.stringify(value).replace(/"/g, "");
  const { videoElemRef } = useSessionVideoControlls()
  const handleAnalyzeEvent = useCallback(() => {
    setCurrentAction({
      ...action,
      props: properties || params,
    });
    videoElemRef?.current?.pause();
    setCurrentScreen(screen);
    setShowDashboardTemplate(true);
  }, [action, params, properties, screen, setCurrentAction, setCurrentScreen, setShowDashboardTemplate, videoElemRef]);

  const handleManageEventClick = useCallback(() => {
    dispatch(
      trackPageViews(null, {
        eventName: 'wa_manage_smart_events_redirect',
        track_type: 'event',
        eventProperty: {
          event_id: action?.id,
          screen_name: screen?.activityName,
          view_name: params?.viewNameUpdated || params?.viewName,
          view_type: params?.viewType,
          element_id: params?.idString,
          gesture_type: action?.name,
          event_name: action?.name,
          type_of_event: 'gesture',
        },
      })
    );
  }, [
    dispatch,
    action?.id,
    action?.name,
    screen?.activityName,
    params?.viewNameUpdated,
    params?.viewName,
    params?.viewType,
    params?.idString,
  ]);

  const isScreenEventCreated = useMemo(() => action?.id && action?.type === 'smart_screenvisit_event', [action]);
  if (isScreenEvent) {
    return (
      <ScreenEventContent
        screen={screen}
        action={action}
        activityName={screen?.activityName}
        isScreenEventCreated={isScreenEventCreated}
      />
    );
  }

  return (
    <ContentWrapper className="expanded-content">
      {isRage && (
        <ul className="list-box">
          <li>
            <span>
              <img alt=" " src={getRageIcon(action.name)} />
            </span>
            Part of rage tap sequence
          </li>
        </ul>
      )}
      <div className="pop-height-wrap">
        {isSmartEvent && (
          <StyledEventGesture
            obj="activityName"
            val={screen?.activityName}
            newSdk={newSdk}
            smartRule={smartRule}
          />
        )}
        {isObject(expandProperties) && !isEmpty(expandProperties) ? (
          map(expandProperties, (val, key) => {
            if (key !== 'anrNumber') {
              return (
                <StyledEventGesture
                  obj={key}
                  val={val}
                  handleCopy={handleCopy}
                  copy={copy}
                  newSdk={newSdk}
                  smartRule={smartRule}
                />
              );
            }
            return null;
          })
        ) : (
          <EmptyProperties newSdk={newSdk} isEvent={isEvent} />
        )}
      </div>
      {!isSharedSession && (
        <ManageEventWrapper>
          {
            !displayAddEventBtn && (isSmartEvent || isEvent) && (
              <TopButtonWrapper>
                <ButtonNew variant="ghost" onClick={handleWatchSessions}>
                  <IconSession />
                  Watch sessions
                </ButtonNew>
                <ButtonNew onClick={handleAnalyzeEvent}>
                  <IconAnalyze />
                  Analyze event
                </ButtonNew>
              </TopButtonWrapper>
            )
          }
          {
            isSmartEvent && (
              <a
                href={`/settings/app/${orgId}/${appId}/smart_events`}
                target="_blank"
                rel="noreferrer"
              >
                <ButtonNew variant="outline" onClick={handleManageEventClick}>
                  <IconNocodeSettings />
                  Manage Smart events
                </ButtonNew>
              </a>
            )
          }
        </ManageEventWrapper>
      )}
      {displayAddEventBtn && !isSmartEvent && !isSharedSession && (
        <BottomWrapper>
          <ButtonNew width="medium" onClick={handleCreateEventBtn}>
            Create event
          </ButtonNew>
        </BottomWrapper>
      )}
    </ContentWrapper>
  );
};
export default memo(GestureCollapseContent);
