import React from 'react'
import { IconButton,
  IconUnknown,
  IconInput,
  IconRadio,
  IconSlider,
  IconViewGroup,
  IconScrollView,
  IconUiTableView,
  IconUiStepper,
  IconDatePicker,
  IconUnresponsive,
  IconTextView
} from './GestureIcon'

const ViewGesturePack = ({ gesture }) => {
  const gestureIcon = (() => {
    switch (gesture) {
      case '-1':
        return <IconUnknown />
      case '1':
        return <IconButton />
      case '2':
        return <IconInput />
      case '3':
        return <IconRadio />
      case '4':
        return <IconSlider />
      case '5':
        return <IconViewGroup />
      case '6':
        return <IconScrollView />
      case '7':
        return <IconTextView />
      case '8':
        return <IconUiTableView />
      case '9':
        return <IconUiStepper />
      case '10':
        return <IconDatePicker />
      case 'unresponsive':
        return <IconUnresponsive />
      default:
        return null
    }
  })()
  return (
    <span>
      {gestureIcon}
    </span>
  )
}
export default ViewGesturePack