import React, { memo } from 'react'
import { ContentWrapper } from './styles'

interface Props {
    activityProperties: Record<string, string>
}

const ScreenActivityContent:React.FC<Props> = ({
    activityProperties
}) => {
  return (
    <ContentWrapper className="expanded-content">
        <div className="pop-height-wrap">
            {
                activityProperties && Object.keys(activityProperties).length > 0 ? 
                Object.entries(activityProperties).map(([key, value]) => (
                    <div className="event-param-name" key={key}>
                        <div className="event-key-title">{key}:</div>
                        <div>{value}</div>
                    </div>
                )) : (
                    <p className="no-eventparam-message">No properties sent</p>
                )
            }
        </div>
    </ContentWrapper>
  )
}

export default memo(ScreenActivityContent)