import React from 'react';
import classNames from 'classnames';
import { WarningOutlined } from '@ant-design/icons';
import { useSessionHeader } from '../../Context';

const SessionEndedContainer = ({
  active,
  videoDuration,
  isCrashedLog,
  onRewind,
}) => {
  const { setSelectedHeaderField } = useSessionHeader();
  return (
    <div
      className={classNames('event-item session-ended', {
        withCrash: isCrashedLog,
        active,
      })}
    >
      <div
        aria-hidden="true"
        onClick={() => onRewind(videoDuration)}
        className={classNames('item-header', `event-header`, {
          active,
        })}
      >
        <h3>
          {isCrashedLog ? (
            <div className="crashed">
              <span className="title">
                <span aria-hidden="true">
                  <WarningOutlined /> App crashed
                </span>
                <p
                  aria-hidden="true"
                  onClick={() => setSelectedHeaderField('crash')}
                >
                  {' '}
                  show details
                </p>
              </span>
            </div>
          ) : (
            'Session ended'
          )}
        </h3>
      </div>
    </div>
  );
};

export default SessionEndedContainer;
