/* eslint-disable no-nested-ternary */
import React, { useState, useEffect, useMemo, useCallback, useRef, memo } from 'react';
import { Menu, Checkbox, Switch, Button } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import { InfoCircleOutlined } from '@ant-design/icons';
import { clone, isEmpty, findIndex, isEqual, uniq, set } from 'lodash';
import ScreenTooltip from 'components/common/ScreenTooltip';
import { setSelectedScreens, skipDeselectedScreensToggler, allScreenCheckToggler, setScreensCategoryFlag } from 'redux/actions/video'
import { convertGetTime } from 'Utils/helpers/commonUtils';
import { useAppScreenListWithSearch } from 'components/features/sessions/hooks/useSessionDetailsSidebar';
import IconSearch from 'public/static/sessions/search.svg'
import { filterTextByOption } from 'components/shared/GlobalFilter/components/utils';
import ButtonNew from 'components/common/ButtonNew/index';
import { trackPageViews } from 'redux/actions/trackingReport';
import styled, { createGlobalStyle } from 'styled-components';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { SelectAllAndClearWrapper } from 'components/common/EventsDropdown'
import { SelectAllAndClear } from 'components/shared/GlobalFilter/components/CommonComponentsV2';
import { ScreenFilterDropdown } from './DropdownStyled'
import { ButtonsBottom, ButtonsEventToggleWrapper, DebounceInputStyled, SearchWrapper } from '../commonStyles';

const GlobalStyles = createGlobalStyle`
  .screens-items-menu-item-group {
    .ant-dropdown-menu-item-group-list {
      margin: 0 !important;
    }
    label.ant-checkbox-wrapper {
      margin: 0;
      width: 100%;
      font-size: 12px;
      line-height: 13px;
      color: #4F4F4F;
      padding: 8px 8px 0 !important;
      .check-option-title {
        width: 100%;
        display: flex;
        justify-content: space-between;
      }
    }
    .ant-checkbox-inner {
      height: 16px !important;
      width: 16px !important;
    }
    .timeline-screen-dropdown-title {
      font-weight: 400 !important;
      &::after {
        display: none;
      }
    }
    .check-option-title {
      position: relative;
    }
    .check-option-count {
    right: 0px !important;
    }
    .screen-with-duration, .screen-without-duration {
      margin-right: 0px;
    }
  }
`

const SkipOptionWrapper = styled.div`
  font-size: 12px;
  line-height: 16px;
  button {
    margin: 5px 6px 10px 0;
  }
`

const ScreenMenuItems =
  ({ screenDropdownVisible, sessionScreensList, sessionScreens, screenDropdownToggler, onVisibleChange }) => {
    const screenInputRef = useRef(null);
    const dispatch = useDispatch()
    const [availableOptions, setAvailableOptions] = useState([]);
    const [fetchedData, setFetchedData] = useState([]);
    const [searchedStrings, setSearchedStrings] = useState({});
    const [isEmptyMessage, showEmptyMessage] = useState(false);
    const [searchText, setSearchText] = useState('');
    const [isApiCall, setApiCall] = useState(false);
    const [tempCheckedBoxes, setTempCheckedBoxes] = useState([]);
    const {
      urlReducer: { appId: appid, sessionid, shareSessionKey, parentType, screenname, sessionid: sessionId},
      screenTimelineReducer: { selectedScreens = [], skipDeselectedToggle, screenList, screenCategoryFlag, allScreenCheckToggle },
      appFilter: { dateSegment }
    } = useSelector((state) => state);

    const newScreensFilter = useFeatureFlag( 'new-screens-filter' ) 

    const { refetch, isLoading } = useAppScreenListWithSearch(
      {
        appid,
        attribute: newScreensFilter ? 'screen_name' : 'session_screen_list',
        date_range: dateSegment,
        dropdownLimit: 9999,
        filter: [],
        search: searchText,
        table: 'session'
      },
      isApiCall
    );

    const fetchedDataSort = useMemo(() => {
      let sortedItems = [];
      const sessionSessionsFilter = sessionScreens.filter((v) =>
        fetchedData.includes(v)
      );
      const newSessionScreen = [
        ...sessionSessionsFilter.filter((v) => selectedScreens.includes(v)),
        ...sessionSessionsFilter.filter((v) => !selectedScreens.includes(v)),
      ];
      if (shareSessionKey || screenCategoryFlag === 'sessionScreens') sortedItems = [...newSessionScreen];
      else {
        const screenNotSessionItems = fetchedData.filter(
          (v) => !sessionScreens.includes(v)
        );
        const allNotSessionScreenItems = [
          ...screenNotSessionItems.filter((v) => selectedScreens.includes(v)),
          ...screenNotSessionItems.filter((v) => !selectedScreens.includes(v)),
        ];
        sortedItems = [...newSessionScreen, ...allNotSessionScreenItems];
      }
      return sortedItems;
    }, [screenCategoryFlag, fetchedData, sessionScreens, screenDropdownVisible]);

    const initialFetch = (list) => {
      setFetchedData(list);
      setAvailableOptions(list);
      setSearchedStrings({ '': list?.length > 0 });
      showEmptyMessage(!list.length);
    };

    const handleSearchInputProps = useCallback(
      async (value) => {
        const inputValue = value.trim() || '';
        let filteredOptions = [];
        let filteredOptionsNew = [];
        const searchedStringsCloned = clone(searchedStrings);
        const availableOptionsCloned = clone(availableOptions);
        let availableOptionsNew = [];

        setSearchText(inputValue);
        setApiCall(false);
        showEmptyMessage(false);
        if (!inputValue) {
          setFetchedData(availableOptionsCloned);
          return;
        }
        filteredOptions = availableOptionsCloned.length
          ? availableOptionsCloned.filter((item) => filterTextByOption(item, inputValue))
          : [];
        if (
          !isEmpty(searchedStringsCloned) &&
          Object.keys(searchedStringsCloned).includes(inputValue) &&
          searchedStringsCloned[inputValue]
        ) {
          setFetchedData(filteredOptions);
          return;
        }
        // const isInputNotSearchable = Object.keys(searchedStringsCloned).reduce(
        //   (...[, key]) =>
        //     inputValue.includes(key) && !searchedStringsCloned[key]
        // );
        // if (isInputNotSearchable) {
        //   showEmptyMessage(true);
        //   setFetchedData([]);
        //   return;
        // }
        // setFetchedData([]);
        if (filteredOptions.length < 10) {
          await setApiCall(true);
          refetch().then((resp) => {
            const remoteDataBy100 = resp?.data?.data
            remoteDataBy100?.length >= 1
              ? (searchedStringsCloned[inputValue] = true)
              : (searchedStringsCloned[inputValue] = false);
            const remoteDataBy100New = remoteDataBy100?.length
              ? remoteDataBy100.filter(
                (val) => !availableOptionsCloned.includes(val)
              )
              : [];
            filteredOptionsNew = [...filteredOptions, ...remoteDataBy100New];
            availableOptionsNew = [...availableOptions, ...remoteDataBy100New];
            showEmptyMessage(!filteredOptionsNew.length);
            setSearchedStrings(searchedStringsCloned);
            setFetchedData(uniq(filteredOptionsNew));
            setAvailableOptions(uniq(availableOptionsNew));
          })
        } else {
          
          filteredOptionsNew = filteredOptions;
          availableOptionsNew = availableOptionsCloned;
          setFetchedData(uniq(filteredOptionsNew));
          setAvailableOptions(uniq(availableOptionsNew));
        }
      },
      [availableOptions, searchedStrings, refetch]
    );

    const handledInputChange = useCallback(
      (e) => {
        if (shareSessionKey || screenCategoryFlag === 'sessionScreens') {
          setSearchText(e.target.value);
          const filteredItems = availableOptions.filter((item) =>
            filterTextByOption(item, e.target.value.trim())
          );
          setFetchedData(filteredItems);
          showEmptyMessage(!filteredItems.length);
        } else handleSearchInputProps(e.target.value);
      },
      [availableOptions, screenCategoryFlag]
    );

    const handleCheckboxGroupChange = useCallback(
      (event) => {
        // if (sessionScreens.includes(event.target.value)) dispatch(setLastMessageByKey({ flag: false }))
        const key = event.target.value
        let newKeys = []
          if (tempCheckedBoxes.includes(key)) {
            newKeys = tempCheckedBoxes.filter(k => k !== key)
            if (newKeys.length === 0) {
              // dispatch(setLastMessageByKey({ flag: true, message: 'At least one screen should be selected.' }))
              return
            }
          }
          else
            newKeys = [...tempCheckedBoxes, key]

        setTempCheckedBoxes(newKeys)
        
        if ( newKeys.length === screenList.length && !allScreenCheckToggle  ) dispatch(allScreenCheckToggler(true))
        if ( newKeys.length !== screenList.length && allScreenCheckToggle  ) dispatch(allScreenCheckToggler(false))
      }, [setTempCheckedBoxes, tempCheckedBoxes, screenList, dispatch, allScreenCheckToggle]
    );

    const reset = useCallback( () => {
      setSearchedStrings({});
      setAvailableOptions([]);
      setFetchedData([]);
      showEmptyMessage(false);
      setSearchText('');
      setTempCheckedBoxes(availableOptions)
    }, [ availableOptions ]);
    const handleClickSessionScreens = useCallback(() => dispatch(setScreensCategoryFlag('sessionScreens')), [ dispatch ] )
    const handleClickAllScreens = useCallback(() => dispatch(setScreensCategoryFlag('allScreens')), [ dispatch ]);

    const handleApply = useCallback(() => {
      if ( searchText?.length ) {
        dispatch(setSelectedScreens(fetchedDataSort))
      } else {
        dispatch(setSelectedScreens(tempCheckedBoxes));
      }
      dispatch(trackPageViews(null, {
        eventName: 'filter_screens',
        track_type: 'event',
        pageName: parentType,
        eventProperty: {
          ...(parentType === 'heatmapsList' && { screenname }),
          ...(parentType === 'heatmapsList' && { sessionid: sessionId }),
        }
      } ) )
      dispatch(allScreenCheckToggler(isEqual(availableOptions.sort(), tempCheckedBoxes.sort())));
      screenDropdownToggler( false );
    }, [searchText?.length, dispatch, parentType, screenname, sessionId, availableOptions, tempCheckedBoxes, screenDropdownToggler, fetchedDataSort]);

    const handleReset = useCallback(() => {
      dispatch(setSelectedScreens(screenList))
      setTempCheckedBoxes( screenList )
      dispatch(allScreenCheckToggler(true));
      setSearchText('');
      dispatch(skipDeselectedScreensToggler(true))
      setTempCheckedBoxes(availableOptions)
      onVisibleChange( false )
    }, [ dispatch, onVisibleChange, availableOptions, screenList ]);

    const handleSelectAll = useCallback( () => setTempCheckedBoxes(availableOptions), [ availableOptions ])
    const handleClearAllOptions = useCallback( () => setTempCheckedBoxes([]), [])

    useEffect(() => {
      reset();
    }, [appid, sessionid]);

    useEffect(() => {
      setTempCheckedBoxes(selectedScreens)
    }, [ selectedScreens ]);

    useEffect(() => {
      if (screenList) initialFetch(screenList);
    }, [screenList, sessionid, appid]);

    useEffect(() => {
      if (screenDropdownVisible && availableOptions.length) {
        showEmptyMessage(false);
        setSearchText('');
        handleSearchInputProps('');
      }
    }, [screenDropdownVisible]);

    useEffect(() => {
      if (screenDropdownVisible) {
        setTimeout(() => {
          screenInputRef.current?.focus({
            preventScroll: true
          })
        }, 0);
      }
    }, [screenDropdownVisible]);

    return (
      <>
        <GlobalStyles />
        <ScreenFilterDropdown>
          { !shareSessionKey && (
            <ButtonsEventToggleWrapper toggleEvent={ screenCategoryFlag === 'allScreens' }>
              <Button onClick={ handleClickAllScreens }>
                All screens
              </Button>
              <Button  onClick={ handleClickSessionScreens }>
                In this session
              </Button>
            </ButtonsEventToggleWrapper>
          ) }
          <SearchWrapper>
            <DebounceInputStyled
              value={searchText}
              placeholder="Search screens"
              debounceTimeout={500}
              inputRef={screenInputRef}
              onChange={handledInputChange}
            />
            <IconSearch />
          </SearchWrapper>
          <SkipOptionWrapper>
            <Switch
              onClick={useCallback(
                (checked) => dispatch(skipDeselectedScreensToggler(checked)),
                []
              )}
              checked={skipDeselectedToggle}
              size="small"
            />{' '}
            <span>Skip deselected screens in video replay</span>
          </SkipOptionWrapper>
          <SelectAllAndClearWrapper />
          <SelectAllAndClear
            handleSelectAllOptions={ handleSelectAll }
            handleClearAllOptions={ handleClearAllOptions }
            disableSelect={ isLoading || tempCheckedBoxes.length === selectedScreens.length }
            disableClear={ !tempCheckedBoxes.length || isLoading  }
          />
          <Menu.ItemGroup key="screen" className="menu-item-group screens-items-menu-item-group">
            <Items
              key={screenCategoryFlag}
              screenCategoryFlag={screenCategoryFlag}
              sessionScreens={sessionScreens}
              sessionScreensList={sessionScreensList}
              availableOptions={availableOptions}
              fetchedDataSort={fetchedDataSort}
              isLoading={isLoading}
              isEmptyMessage={isEmptyMessage}
              handleCheckboxGroupChange={handleCheckboxGroupChange}
              tempCheckedBoxes={ tempCheckedBoxes}
              setTempCheckedBoxes={ setTempCheckedBoxes }
            />
          </Menu.ItemGroup>
          <ButtonsBottom>
            <ButtonNew 
              onClick={ handleReset }
              variant='ghost'
            >
              Reset
            </ButtonNew>
            <ButtonNew
              onClick={ handleApply }
              variant='primary'
            >
              Apply
            </ButtonNew>
          </ButtonsBottom>
        </ScreenFilterDropdown>
      </>
    );
}

const Items = memo((props) => {
  const {
    sessionScreensList,
    availableOptions,
    fetchedDataSort,
    isLoading,
    isEmptyMessage,
    handleCheckboxGroupChange,
    sessionScreens,
    screenCategoryFlag,
    tempCheckedBoxes,
    setTempCheckedBoxes
  } = props
  const dispatch = useDispatch()
  const { selectedScreens = [], allScreenCheckToggle } = useSelector((state) => state.screenTimelineReducer);
  const allScreenToggler = useCallback(
    (e) => {
      // dispatch(setLastMessageByKey({ flag: false }))
      if(isEmptyMessage) return;
      let newData = []
      if (screenCategoryFlag === 'sessionScreens') {
        if (!e.target.checked)
          newData = selectedScreens.filter(v => !sessionScreens.filter(x => x !== fetchedDataSort[0]).includes(v))
        else newData = uniq([...sessionScreens, ...selectedScreens])
      } else if (screenCategoryFlag === 'allScreens') {
        if (!e.target.checked)
          // dispatch(setLastMessageByKey({ flag: true, message: 'At least one screen should be selected.' }))
          newData = availableOptions.filter(v => v === fetchedDataSort[0])
        else newData = availableOptions
      }
      dispatch(allScreenCheckToggler(e.target.checked))
      setTempCheckedBoxes(newData)
    },
    [screenCategoryFlag, availableOptions, fetchedDataSort, setTempCheckedBoxes, isEmptyMessage, selectedScreens, sessionScreens, dispatch]
  );

  useEffect(() => {
    const isChecked = () => {
      if (screenCategoryFlag === 'sessionScreens')
        return selectedScreens.filter(e => sessionScreens.indexOf(e) !== -1).length === sessionScreens.length
      return isEqual(availableOptions.sort(), selectedScreens.sort())
    }
    selectedScreens.length && availableOptions.length && dispatch(allScreenCheckToggler(isChecked()))
  }, [screenCategoryFlag, selectedScreens])

  const renderScreens = useMemo(() => {
    if (isLoading)
      return <span className="loading">loading...</span>
    if (!isEmptyMessage)
      return <div className="ant-checkbox-group">
        {fetchedDataSort.map((v) => {
          const indexByScreen = findIndex(sessionScreensList, {
            screenName: v,
          });
          return (
            <Checkbox
              checked={tempCheckedBoxes.indexOf(v) > -1}
              onChange={handleCheckboxGroupChange}
              value={v}
              key={v}
              className="check-option"
            >
              <div className="check-option-title">
                <ScreenTooltip
                  onRenderScreen={(renderScreen) => <span className={indexByScreen > -1
                    ? 'screen-with-duration'
                    : 'screen-without-duration'}>{renderScreen}</span>}
                  originalScreenName={v}
                />
                {Boolean(indexByScreen > -1) && (
                  <span className="check-option-count">
                    {typeof sessionScreensList[indexByScreen]
                      .duration === 'number'
                      ? convertGetTime(
                        {
                          durationInSecs: sessionScreensList[indexByScreen].duration,
                          roundFalse: false
                        }
                      )
                      : ''}
                  </span>
                )}
              </div>
            </Checkbox>
          );
        })}
      </div>
    return <div className="text-center">
        <InfoCircleOutlined /> No matching event or screen name
      </div>
  }, [handleCheckboxGroupChange, isLoading, isEmptyMessage, fetchedDataSort, sessionScreensList, tempCheckedBoxes])

  return renderScreens
})
export default memo(ScreenMenuItems)
