import styled from 'styled-components';
import { Select, Input } from 'antd';

/* for screen level styles */
export const AppLogWrapper = styled.div`
  background: #ffffff;
  padding: 10px;
  padding-top: 0;
  overflow-y: auto;
  height: calc(100vh - 212px);
  &::-webkit-scrollbar {
    width: 5px;
    height: 5px;
  }
  &::-webkit-scrollbar-track{
      border-radius: 6px;
  }
  &::-webkit-scrollbar-thumb {
    background-color: #babec5;
    border-radius: 6px;
    transition: background-color 1s;
    &:hover{
      background-color: #747c8b;
    }
  }
  .log-wrapper {
    height: ${({size}) => size < 4 ? `calc((100% / ${size}) - 10px)` : `auto`};
  }

  .log-wrapper:only-of-type {
    height: ${({firstChildSize}) => firstChildSize.length !==0 && firstChildSize.length < 23 ? `calc((32px * ${firstChildSize}))` : 'auto'} !important;
  }

  .log-wrapper:nth-of-type(1) {
    height: ${({firstChildSize, size}) => size < 4 && firstChildSize > 1 && firstChildSize < 11 ? `calc((32px * ${firstChildSize}) + 40px)` : ''} !important;
  }

  .log-wrapper:nth-of-type(2) {
    height: ${({secondChildSize, size}) => size < 4 && secondChildSize > 1 && secondChildSize < 11 ? `calc((32px * ${secondChildSize}) + 40px)` : ''} !important;
  }

  .log-wrapper:nth-of-type(2) {
    height: ${({secondChildSize, size, firstChildSize}) => size === 2 && firstChildSize !== 0 && firstChildSize < 11 && secondChildSize !== 0 ? `calc(32px * ${10 + firstChildSize})` : ''} !important;
  }

  .log-wrapper .log-content-wrapper {
    min-height: ${({size, firstChildSize, secondChildSize}) => {
      if (size < 4 && (firstChildSize === 1 || secondChildSize === 1)) {
        return '32px';
      }
      return size < 4 ? 'calc(100% - 40px)' : '200px';
    }};
    max-height: ${({size, firstChildSize, secondChildSize}) => {
      if (size < 4 && (firstChildSize === 1 || secondChildSize === 1)) {
        return 'none';
      }
      return size < 4 ? 'calc(100% - 40px)' : '200px';
    }};
    height: ${({size, firstChildSize, secondChildSize}) => {
      if (size < 4 && (firstChildSize === 1 || secondChildSize === 1)) {
        return 'auto';
      }
      return size < 4 ? '' : '200px';
    }};
  }
`;

