/* eslint-disable react/jsx-props-no-spreading */
/* eslint-disable jsx-a11y/click-events-have-key-events */
/* eslint-disable jsx-a11y/no-static-element-interactions */
/* eslint-disable react/no-array-index-key */
import React, {
  memo,
  useCallback,
  useMemo,
  useRef,
  useState,
  useEffect,
} from 'react';
import { Skeleton, Tabs } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import { setFilteredTimeline } from 'redux/actions/video';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import AILogo from 'public/static/sessions/TaraMicroLogo.svg'
import {
  NextUserSessionIcon,
  PreviousUserSessionIcon,
} from 'components/svg_files';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import Router from 'next/router';
import { clone, isArray, toLower } from 'lodash';
import { convertGetTime, mapEquals } from 'Utils/helpers/commonUtils';
import styled, { createGlobalStyle, css } from 'styled-components';
import { trackPageViews } from 'redux/actions/trackingReport';
import { fetchPlanHatApi } from 'redux/actions/common';
import { useShareSessionAIFeature } from 'components/features/sessions/hooks/useSessionDetail';
import {
  TimeLineWithMultiSkip,
  TimeLineWithSkip,
} from './ScreenTimeLine/ScreenTimeLineWithSkip';
import { findGesturesByTime } from '../Video/utils';
import InsightsTab from './InsightsTab';
import {
  useSessionVideoContext,
  useSessionTimeLine,
  useSessionVideoControlls,
  useSessionSidebar,
  useScreenLayoutContext,
} from '../Context';
import SessionNoteAddForm from './SessionNotes/SessionNoteAddForm';
import SessionInfo from './ScreenTimeLine/SessionInfo';
import TimeLineFilterContainer from './ScreenTimeLine/TimelineFilterContainer';
import SessionEndedContainer from './ScreenTimeLine/SessionEndedContainer';
import AIAnalyzedBanner from './AIAnalyzedBanner';
import {
  DetailsSidebar,
  SessionNoteWrap,
  Wrapper,
  ActionUserSession,
  ActionUserSessionItem,
  SessionInfoWrapper,
  TimeLineSkeleton,
} from './ScreenTimeLine/SessionDetailSideBarStyled';
import AppLogs from './AppLogs';
import AppLogInfo from './AppLogs/AppLogInfo';

const ANDROID_SDK_VERSION_NUMBER_THRESHOLD = 555; // 3.4.0
const IOS_SDK_VERSION_NUMBER_THRESHOLD = 20220413; // 3.4.1

const { TabPane } = Tabs;
const EmptyMap = new Map();

const InsightsTabHeaderWrapper = styled.div`
  display: flex;
  align-items: center;
  gap: 6px;
  ${({isAISession}) => !isAISession && css`
    svg path {
          filter: grayscale(1) invert(0);
          transform: rotateZ(180deg);
          opacity: 0.8;
    }
  `}
`

const InsightsTabWrapper = styled.div`
  padding: 16px 12px;
  height: 100%;
`

const AICustomStyles = createGlobalStyle`
  .session-detail-tabs {
    .ant-tabs-nav-wrap {
      &::before, &::after {
        opacity: 0 !important;
      }
    }
    .ant-tabs-nav {
      padding-left: 0 !important;
      .ant-tabs-nav-list {
        .ant-tabs-tab {
          margin-right: 0 !important;
            min-width: 105px;
          [aria-selected="true"] {
            .insights-tab-header {
              color: #EE5FDD;
            }
          }
        }
        .ant-tabs-ink-bar {
          height: 2px !important;
          ${ ( { aiInsightsTabIsSelected } ) => aiInsightsTabIsSelected && css`
            background: linear-gradient(233.37deg, #EE5EDD 48.25%, #49C5FF 81.95%);
          ` }
        }
      }
    }
    .ant-tabs-nav-more {
      transition: background 0.1s ease-in-out;
      &.ant-tabs-dropdown-open {
        background-color: #DFEAFF !important;
      }
    }
  }
  .session-detail-tabs-popup {
    .ant-tabs-dropdown-menu {
      border-radius: 8px;
      border: 1px solid #E8E8EB;
      box-shadow: none;
      padding: 10px;
      li {
        padding: 6px 8px;
        border-radius: 4px;
      }
    }
  }
`

const Container = styled.div`
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
`

const SessionDetailSideBar = ({
  multiScreenSkippedData,
  uploadedOn,
  detailErrorMessage,
}) => {
  const { isPlaying } = useSessionVideoContext();
  const { videoElemRef } = useSessionVideoControlls();
  const { setSelectedTab, selectedTab } = useSessionSidebar();
  const [currentGestures, setCurrentGestures] = useState(EmptyMap);
  const [screenDropdownVisible, screenDropdownToggler] = useState(false);

  const {
    sessionDetail,
    rewind,
    currentScreen,
    currentTimeRef,
    nearestSession,
    sessionLogs,
    isWebSession: isWebSDK,
  } = useSessionTimeLine();
  const { getScreenLayoutData } = useScreenLayoutContext();
  const { previousSessionId, nextSessionId } = nearestSession || {};
  const dispatch = useDispatch();
  const { aiSessionFeatureAllowed: aiSessionsEnabled } = useRestrictionContext() || {}
  
  const { isAppLogEnabled, device, _id: detailSessionId } = sessionDetail || {};
  const platform = device?.platform;

  const isAppLogValid = useMemo(() => {
    if (device) {
      const threshold =
        platform === 1 ? ANDROID_SDK_VERSION_NUMBER_THRESHOLD : IOS_SDK_VERSION_NUMBER_THRESHOLD;
      return (device?.sdkVersionNumber ?? 0) >= threshold;
    }
    return null;
  }, [device, platform]);

  const isAppLogFeatureValid = isAppLogValid && isAppLogEnabled;

  const {
    urlReducer: {
      appId,
      shareSessionKey,
      sessionpage,
      parentType,
      notetab,
      sessionid,
      secondarysessionid,
      eventpage,
    },
    screenTimelineReducer: {
      selectedEventField,
      selectedGestureField,
      selectedScreens = [],
      screenList,
    },
    appFilter,
  } = useSelector((state) => state);
  const sessionId = parentType==='aiSessionsList' ? secondarysessionid : sessionid;
  const segment = appFilter?.session?.segment;

  // Check if shared session has AI enabled
  const isSharedSession = parentType === 'shareSession';
  const { data: aiFeatureData } = useShareSessionAIFeature(
    shareSessionKey,
    aiSessionsEnabled && isSharedSession
  );
  const isAIEnabledForSharedSession = aiFeatureData?.data?.data?.is_ai_enabled || false;
  const screenTimeLineData = useMemo(
    () => sessionDetail?.screenTimeline?.activities || [],
    [sessionDetail]
  );

  // create a Map of event and gesture names
  const selectedFields = useMemo(
    () =>
      selectedEventField
        .concat(selectedGestureField)
        .reduce((acc, { name }) => {
          acc[name] = true;
          return acc;
        }, {}),
    [selectedEventField, selectedGestureField]
  );

  const selectedEventFieldReduced = useMemo(
    () => selectedEventField?.filter( event => !event?.isSmartEvent ).reduce((acc, { name }) => {
      acc[name] = true;
      return acc;
    }, {}),
    [selectedEventField]
  );

  const selectedSmartEventFieldReduced = useMemo(
    () => selectedEventField?.filter( event => event?.isSmartEvent ).reduce((acc, { name }) => {
      acc[name] = true;
      return acc;
    }, {}),
    [selectedEventField]
  );

  const selectedGestureFieldReduced = useMemo(
    () => selectedGestureField.reduce((acc, { name }) => {
      acc[name] = true;
      return acc;
    }, {}),
    [selectedGestureField]
  );

  const currentScrenRef = useRef(currentScreen);

  const videoDuration = useMemo(
    () => videoElemRef?.current?.duration || 0,
    [videoElemRef?.current?.duration]
  );

  const videoCurrentTime = useMemo(
    () => videoElemRef?.current?.currentTime,
    [videoElemRef?.current?.currentTime]
  );

  const allActions = useMemo(() => {
    const screens = sessionDetail?.screenTimeline?.activities || [];
    const concatActions = screens.reduce((acc, screen) => {
      const { actions } = screen;
      return acc.concat(actions);
    }, []);
    return concatActions;
  }, [sessionDetail?.screenTimeline?.activities]);

  const seekGesture = useCallback(() => {
    const time = currentTimeRef.current;

    if (allActions) {
      const gesturesMap = findGesturesByTime(allActions, time).reduce(
        (acc, action) => {
          acc.set(action, 1);
          return acc;
        },
        new Map()
      );

      setCurrentGestures((oldGestures) =>
        mapEquals(gesturesMap, oldGestures) ? oldGestures : gesturesMap
      );
    }
  }, [allActions, currentTimeRef]);

  useEffect(() => {
    currentScrenRef.current = currentScreen;
  }, [currentScreen]);

  useEffect(() => {
    let timeout = null;
    let last;

    const step = () => {
      const now = new Date();
      if (!last || now - last > 16) {
        last = now;
        seekGesture();
      }

      timeout = requestAnimationFrame(step);
    };

    if (isPlaying) {
      timeout = requestAnimationFrame(step);
    }

    return () => {
      cancelAnimationFrame(timeout);
    };
  }, [isPlaying, seekGesture]);

  const handleRewind = useCallback(
    (newTime) => {
      rewind(newTime);
    },
    [rewind]
  );

  const handleVideoSeek = useCallback(() => {
    setTimeout(seekGesture, 10);
  }, [videoElemRef, seekGesture]);

  useEffect(() => {
    const videoElem = videoElemRef.current;

    if (videoElem) {
      videoElem.addEventListener('seeked', handleVideoSeek);

      return () => {
        videoElem.removeEventListener('seeked', handleVideoSeek);
      };
    }

    return undefined;
  }, [videoElemRef, handleVideoSeek]);

  const filteredScreenTimeLineData = useMemo(() => {
    const timeLineData = sessionDetail?.screenTimeline?.activities;
    return (
      timeLineData &&
      timeLineData.map((timeLine) => {
        const tempTimeLine = { ...timeLine };

        return {
          ...timeLine,
          actions: tempTimeLine.actions.filter(
            ({ name }) => selectedFields[name]
          ),
        };
      })
    );
  }, [sessionDetail?.screenTimeline?.activities, selectedFields]);

  useEffect(() => {
    dispatch(setFilteredTimeline(filteredScreenTimeLineData));
  }, [filteredScreenTimeLineData]);

  const logInfo = useMemo(() => {
    if (!isAppLogEnabled)
      return 'App logs has been disabled in the app settings page';
    if (sessionLogs.length < 1)
      return 'App logs are not recorded due to old sdk versions';
    return null;
  }, [isAppLogEnabled, sessionLogs]);

  useEffect(() => {
    if (selectedTab === 'logs') {
      dispatch(
        trackPageViews(null, {
          eventName: 'visit_log',
          track_type: 'event',
          eventProperty: {
            sessionId,
            appLogAvailable: isAppLogEnabled || false,
            ...(logInfo && { description: logInfo }),
          },
        })
      );
      dispatch(
        fetchPlanHatApi({
          action: 'Visit Log',
          info: {
            sessionId,
            appLogAvailable: isAppLogEnabled || false,
          },
        })
      );
    }
  }, [selectedTab]);

  const handleTabChange = useCallback((key) => {
    setSelectedTab(key);
    dispatch(
      fetchPlanHatApi({
        action: `Click on ${toLower(key)} tab session detail page`,
      })
    );

    if (key === 'aiInsights') {
      dispatch(
        trackPageViews(null, {
          eventName: 'wa_sessions_click_insights',
          track_type: 'event',
          eventProperty: {
            source: 'insights_tab',
          },
        })
      )
    }
  }, [dispatch, setSelectedTab]);

  const getUserSessionUrl = useCallback(
    (id) => {
      let url = '';
      let query = '';
      if (parentType === 'sessionsList') {
        url = urlSegmentEncoder(
          `/app/${appId}/sessions/list/${sessionpage || 1}/${id}?`,
          segment
        );
        query = `appId=${appId}&parentType=sessionsList&sessionid=${id}&sessionpage=${
          sessionpage || 1
        }`;
      }
      if (parentType === 'aiSessionsList') {
        url = urlSegmentEncoder(
          `/app/${appId}/sessions/list/${sessionpage || 1}/${id}?`,
          segment
        );
        query = `appId=${appId}&parentType=aiSessionsList&sessionid=${id}&sessionpage=${
          sessionpage || 1
        }`;
      }
      if (parentType === 'eventsList') {
        url = urlSegmentEncoder(
          `/app/${appId}/events/list/${eventpage || 1}/${id ? `/${id}` : ''}?`,
          segment
        );
        query = `appId=${appId}&parentType=eventsList${
          id ? `&sessionid=${id}` : ''
        }&eventpage=${eventpage || 1}&starttime=0`;
      }
      return { url, query };
    },
    [appId, parentType, segment, sessionpage, eventpage]
  );

  const changeUserSession = (id) => {
    const { url, query } = getUserSessionUrl(id);
    Router.push(`/integration?${query}`, url);
  };

  const trackUserSessionChange = (name) => {
    dispatch(
      trackPageViews(null, {
        eventName: name,
        track_type: 'event',
        eventProperty: { userId: sessionDetail?.userProperty?.uxcamuserid },
      })
    );
  };

  const handlePreviousUserSession = useCallback(() => {
    trackUserSessionChange('previous_user_session');
    changeUserSession(previousSessionId);
    dispatch(
      fetchPlanHatApi({ action: 'Previous session session detail page' })
    );
  }, [previousSessionId]);

  const handleNextUserSession = useCallback(() => {
    trackUserSessionChange('next_user_session');
    changeUserSession(nextSessionId);
    dispatch(fetchPlanHatApi({ action: 'Next session session detail page' }));
  }, [nextSessionId]);

  const screenTimeLineDataCloned = clone(screenTimeLineData);

  useEffect(() => {
    notetab && setSelectedTab('notes');
  }, [notetab]);

  const renderComponent = useMemo(() => {
    if (
      multiScreenSkippedData.seqArrayIndexList?.length &&
      selectedScreens.length
    ) {
      return multiScreenSkippedData.screenTimeLineDataCloned.map(
        (screen, eventIndex) => {
          const viewtime = screen.endTime - screen.time;
          if (isArray(screen)) {
            return (
              <TimeLineWithMultiSkip
                key={eventIndex}
                screenList={screen}
                onRewind={handleRewind}
                sessionDetail={sessionDetail}
                currentGestures={currentGestures}
                selectedFields={selectedFields}
                selectedEventFields={selectedEventFieldReduced}
                selectedSmartEventFields={selectedSmartEventFieldReduced}
                selectedGestureFields={selectedGestureFieldReduced}
                currentScreen={currentScreen}
                screenDropdownToggler={screenDropdownToggler}
                uploadedOn={uploadedOn}
              />
            );
          }
          return (
            <TimeLineWithSkip
              key={viewtime + eventIndex}
              eventIndex={eventIndex}
              screen={screen}
              active={
                selectedScreens.includes(screen.activityName) &&
                currentScreen === screen
              }
              onRewind={handleRewind}
              sessionDetail={sessionDetail}
              currentGestures={currentGestures}
              selectedFields={selectedFields}
              selectedEventFields={selectedEventFieldReduced}
              selectedSmartEventFields={selectedSmartEventFieldReduced}
              selectedGestureFields={selectedGestureFieldReduced}
              engagementTime={
                viewtime < 60
                  ? `${Math.round(viewtime)} sec`
                  : convertGetTime({
                      durationInSecs: viewtime,
                      roundFalse: false,
                    })
              }
              isSkippedScreenActivity={
                !selectedScreens.includes(screen.activityName) ||
                !screenList.includes(screen.activityName)
              }
              screenDropdownToggler={screenDropdownToggler}
              uploadedOn={uploadedOn}
            />
          );
        }
      );
    }

    return screenTimeLineDataCloned?.map((screen, eventIndex) => {
      const viewtime = screen.endTime - screen.time;
      return (
      <TimeLineWithSkip
        key={viewtime + eventIndex}
        eventIndex={eventIndex}
        screen={screen}
        active={
          selectedScreens.includes(screen.activityName) &&
          currentScreen === screen
        }
        onRewind={handleRewind}
        sessionDetail={sessionDetail}
        currentGestures={currentGestures}
        selectedFields={selectedFields}
        selectedEventFields={selectedEventFieldReduced}
        selectedSmartEventFields={selectedSmartEventFieldReduced}
        selectedGestureFields={selectedGestureFieldReduced}
        engagementTime={
          viewtime < 60
            ? `${Math.round(viewtime)} sec`
            : convertGetTime({
                durationInSecs: viewtime,
                roundFalse: false,
              })
        }
        isSkippedScreenActivity={
          !screenList.length
            ? false
            : !selectedScreens.includes(screen.activityName) ||
              !screenList.includes(screen.activityName)
        }
        screenDropdownToggler={screenDropdownToggler}
        uploadedOn={uploadedOn}
      />
    )});
  }, [multiScreenSkippedData, uploadedOn, selectedScreens, screenTimeLineDataCloned, currentScreen, handleRewind, sessionDetail, currentGestures, selectedFields, selectedEventFieldReduced, selectedSmartEventFieldReduced, selectedGestureFieldReduced, screenList]);

  const isAISessionPage = parentType === 'aiSessionsList' || parentType === 'aiSessionsDetail'
  const shouldShowInsightsTab = aiSessionsEnabled && (isAISessionPage || (isSharedSession && isAIEnabledForSharedSession))
  
  return (
    <DetailsSidebar>
      { shouldShowInsightsTab && (
        <AICustomStyles
          aiInsightsTabIsSelected={selectedTab === 'aiInsights'}
        />
      ) }
      <TimeLineSkeleton
        loading={
          shareSessionKey
            ? false
            : detailErrorMessage === undefined && sessionId !== detailSessionId
        }
        active
        paragraph={{ rows: 25 }}
      >
        <div
          className="session-sidebar video-action-timeline"
          data-intercom-target="Session sidebar"
        >
          <Tabs
            activeKey={selectedTab || 'activity'}
            onChange={handleTabChange}
            className="session-detail-tabs"
            popupClassName='session-detail-tabs-popup'
          >
            <TabPane
              tab={<span data-intercom-target="Tab Activity">Activity</span>}
              key="activity"
            >
              <Container>
                { (sessionDetail?.sessionanalyzedbyai || isAIEnabledForSharedSession) && shouldShowInsightsTab && (
                  <AIAnalyzedBanner setSelectedTab={ setSelectedTab } />
                ) }
                <TimeLineFilterContainer
                  screenDropdownToggler={screenDropdownToggler}
                  screenDropdownVisible={screenDropdownVisible}
                  uploadedOn={uploadedOn}
                />
                <Wrapper>
                  <div className="event-wrapper">
                    {renderComponent}
                    {videoDuration && screenTimeLineData ? (
                      <SessionEndedContainer
                        active={
                          currentScreen === null &&
                          videoCurrentTime === videoDuration
                        }
                        videoDuration={videoDuration}
                        isCrashedLog={sessionDetail?.isCrashedLog}
                        onRewind={handleRewind}
                      />
                    ) : null}
                  </div>
                  {!shareSessionKey && ['sessionsList', 'aiSessionsList', 'eventsList', 'nocodeEventsList'].includes(parentType) && !isAISessionPage ? (
                    <Skeleton
                      loading={detailSessionId !== sessionId}
                      active
                      paragraph={{ rows: 1 }}
                    >
                      <ActionUserSession>
                        <ActionUserSessionItem
                          data-intercom-target="Previous Session"
                          clickable={previousSessionId}
                          onClick={() => handlePreviousUserSession()}
                        >
                          <PreviousUserSessionIcon /> Previous user session
                        </ActionUserSessionItem>
                        <ActionUserSessionItem
                          data-intercom-target="Next Session"
                          clickable={nextSessionId}
                          onClick={() => handleNextUserSession()}
                        >
                          {' '}
                          Next user session <NextUserSessionIcon />
                        </ActionUserSessionItem>
                      </ActionUserSession>
                    </Skeleton>
                  ) : null}
                </Wrapper>
              </Container>
            </TabPane>
            <TabPane
              tab={
                <span data-intercom-target="Tab Session Info">
                  { aiSessionsEnabled && isAISessionPage ? 'Info' : 'Session Info' }
                </span>
              }
              key="sessionInfo"
            >
              <SessionInfoWrapper className="session-info">
                <SessionInfo />
              </SessionInfoWrapper>
            </TabPane>
            { shouldShowInsightsTab && (
              <TabPane
                tab={
                  <InsightsTabHeaderWrapper className='insights-tab-header' isAISession={ sessionDetail?.sessionanalyzedbyai || isAIEnabledForSharedSession }>
                    <AILogo />
                    Insights
                  </InsightsTabHeaderWrapper>
                }
                key="aiInsights"
              >
                <InsightsTabWrapper>
                  <InsightsTab isAISession={ sessionDetail?.sessionanalyzedbyai || isAIEnabledForSharedSession } />
                </InsightsTabWrapper>
              </TabPane>
            ) }
            {!shareSessionKey ? (
              <TabPane
                tab={<span data-intercom-target="Tab Notes">Notes</span>}
                key="notes"
              >
                <SessionNoteWrap className="note-info">
                  <SessionNoteAddForm redirectToVideo={handleRewind} />
                </SessionNoteWrap>
              </TabPane>
            ) : null}
            {!shareSessionKey && ['sessionsList', 'aiSessionsList', 'issues'].includes(parentType) && !isWebSDK ? (
              <TabPane
                tab={<span data-intercom-target="Tab Logs">Logs</span>}
                key="logs"
              >
                {isAppLogFeatureValid ? (
                  <AppLogs />
                ) : (
                  <AppLogInfo
                    platform={platform}
                    isAppLogValid={isAppLogValid}
                    isAppLogRecorded
                  />
                )}
              </TabPane>
            ) : (
              ''
            )}
          </Tabs>
        </div>
      </TimeLineSkeleton>
    </DetailsSidebar>
  );
};
export default memo(SessionDetailSideBar);
