import ExpandTextLines from 'components/shared/ExpandLines';
import { getActivityDisplayTime } from 'components/shared/Sessions/Video/utils';
import { ErrorIcon, InfoIcon, WarningIcon, DebugIcon, VerboseIcon, FaultIcon, UndefinedIcon } from 'components/svg_files';
import React, { useCallback, useRef } from 'react';
import { useVirtual } from 'react-virtual';
import { LogContainerItem, LogContainerWrapper, LogContentWrapper, LogContainerItemTimeSpan, LogContainerItemIconSpan, LogContainerItemTextSpan, NoLogsWrapper } from './styles/AppLogStyles';

export const mapLogsIcon = {
  i: <InfoIcon />,
  d: <DebugIcon />,
  e: <ErrorIcon />,
  w: <WarningIcon />,
  v: <VerboseIcon />,
  f: <FaultIcon />,
  u: <UndefinedIcon />,
};

const LogContent = ({ logs: items, handleRewind, size }) => {
  const parentRef = useRef();

  const rowVirtualizer = useVirtual({
    size: items?.length,
    parentRef,
    estimateSize: useCallback(() => 28, []),
    overscan: 30,
  });

  return (
    <>
    {items?.length > 0 ?
      <LogContentWrapper ref={parentRef} className='log-content-wrapper'
       style={{
        height: `${size < 4 && items?.length > 1 && items?.length < 7 ? `calc((32px * ${items.length}))` : 'auto'}`
       }}
      >
        <LogContainerWrapper className='log-container'>
          {rowVirtualizer.virtualItems?.map((virtualRow) => (
            <LogContainerItem
              key={virtualRow.index}
              width={parentRef?.current?.getBoundingClientRect().width}
              style={{
                transform: `translateY(${virtualRow.start}px)`,
                transition: `transform 0.5s ease-in-out`,
                // height: `${virtualRow.size}px`,
              }}
            >
              <LogContainerItemTimeSpan onClick={(e) => handleRewind(e, items[virtualRow.index]?.timeLine)}>
                {getActivityDisplayTime(items[virtualRow.index]?.timeLine)}
              </LogContainerItemTimeSpan>
              <LogContainerItemIconSpan>
                {mapLogsIcon[items[virtualRow.index]?.level]}
              </LogContainerItemIconSpan>
              <LogContainerItemTextSpan>
                <ExpandTextLines
                  width={parentRef?.current?.getBoundingClientRect().width - 100}
                >
                  {items[virtualRow.index]?.message}
                </ExpandTextLines>
              </LogContainerItemTextSpan>
            </LogContainerItem>
          ))}
        </LogContainerWrapper>
      </LogContentWrapper> : <NoLogsWrapper> No logs found for this screen. </NoLogsWrapper>}
    </>
  );
};

export default LogContent;
