/* eslint-disable react/jsx-no-useless-fragment */
/* eslint-disable react/jsx-props-no-spreading */
import { Collapse, Tooltip } from 'antd';
import React, { memo, useCallback, useMemo, useState } from 'react';
import classNames from 'classnames';
import { SidebarCaretIcon } from 'components/svg_files';
import styled from 'styled-components';
import { getActivityDisplayTime } from 'components/shared/Sessions/Video/utils';
import { useSessionSidebar, useSessionTimeLine } from 'components/shared/Sessions/Context';
import IconPlus from 'public/static/icon-plus-box.svg';
import IconMinus from 'public/static/icon-edit-box.svg';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useSelector, useDispatch } from 'react-redux';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { getActionType, identifyEventName } from 'Utils/helpers/SessionUtils';
import GesturePack from './GesturePack';
import GesturePopover from './GesturePopover';
import { RageIcon } from '../IconSvg';
import NewGestureCollapseContent from './NewGestureCollapseContent';
import { compareSDKVersion, smartEventsSupportedSDK } from './helpers';

const { Panel } = Collapse;

const CustomLiWrap = styled.li`
  width: ${({ width }) => `${width}px !important`};
`
const AddEventWrapper = styled.div`
  height: 16px;
  width: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  svg path, svg rect {
    transition: all 0.1s ease-in-out;
  }
  button {
    height: 16px;
    width: 16px; 
    background: transparent;
    border: none;
    outline: none;
    cursor: pointer;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 0;
    transition: all 0.1s ease-in-out;
    &:hover {
      background: #F8FAFF;
      border-radius: 2px;
    }
  }
  &:hover {
    svg {
      path {
        fill: #5D97FF;
      }
      rect {
        fill: #DFEAFF;
      }
    }
  }
`
const CollapseWrapper = styled(Collapse)`
  background-color: #ffffff !important;
  .ant-collapse-item.ant-collapse-item-active {
    margin-top: 5px;
    padding: 5px 0;
    border: 1px solid #5D97FF;
  }
  .ant-collapse-content > .ant-collapse-content-box {
    padding: 0;
  }
`
const ActivityTimeWrap = styled.span`
  font-size: 12px;
  margin-left: 13px;
  color: rgba(73, 87, 110, 0.6);
`
const GroupedGestureWrap = styled.span`
  font-size: 13px;
  font-weight: 500;
  color: #49576E;
  svg {
    position: relative;
    top: 2px;
    margin: 0 2px;
    width: 18px;
    height: 18px; 
  }
`
const SidebarCaretIconWrap = styled.span`
  margin-right: 10px;
`

export const GestureBox = memo((props) => {
  const { sessionDetail } = useSessionTimeLine();
  const { setSelectedScreenName } = useSessionSidebar()
  const { setManagePopupOpen, setCurrentAction, setCurrentScreen, noCodeEventsFeatureFlag, setScreenEventModalOpen } = useNoCodeEventsContext()
  const { urlReducer } = useSelector( state => state )
  const { parentType, sessionid } = urlReducer
  const dispatch = useDispatch()
  const { device, newSdk } = sessionDetail || {};
  const { active, containerWidth, gestureIndex, action, onRewind, screen } = props;
  const { properties, isRage, name, time, params } = action;
  const { isEvent, isSmartEvent, isGesture, isScreenEvent } = getActionType(action);
  const [collapseActiveKey, setCollapseActiveKey] = useState('');
  const collapseKey = useMemo(
    () => `${gestureIndex}-${name}-${time}`,
    [gestureIndex, name, time]
  );

  const displayAddEventBtn = useMemo( () => {
    if ( !noCodeEventsFeatureFlag || !device?.platform || !device?.sdkVersion || parentType === 'shareSession' ) return false
    const isAllowedGesture = ['Single Tap', 'Double Tap', 'Swipe Up', 'Swipe Down', 'Swipe Left', 'Swipe Right', 'Long Press', 'Zoom In', 'Zoom Out' ].includes( name )
    const isSDKNative = device.sdkPluginType === "native" || device.sdkPluginType === 'react-native'
    const isSDKFlutter = device.sdkPluginType === 'flutter'
    let isSDKVersionValid = false
    if ( isSDKNative ) {
      // device.platform === 1 is Android
      isSDKVersionValid = compareSDKVersion( device.sdkVersion, device.platform === 1 ? '3.0.7' : '3.6.0' )
    } else if ( isSDKFlutter ) {
      // device.platform === 1 is Android
      isSDKVersionValid = compareSDKVersion( device.sdkVersion, device.platform === 1 ? '3.7.1' : '3.7.0' )
    } else if ( smartEventsSupportedSDK.includes( device.sdkPluginType ) ) {
      isSDKVersionValid = true
    }

    return isAllowedGesture && isSDKVersionValid
  }, [noCodeEventsFeatureFlag, device?.platform, device?.sdkVersion, device.sdkPluginType, parentType, name] )

  const handleCollapseBtnClick = useCallback( ( key ) => {
    const recentKey = collapseActiveKey === key ? '' : key;
    setCollapseActiveKey(recentKey);
    if ( recentKey ) {
      dispatch( trackPageViews( null, {
        eventName: 'wa_activity_expand',
        track_type: 'event',
        eventProperty: {
          session_id: sessionid, 
          element_type: ( isEvent || isSmartEvent || isScreenEvent ) ? 'event' : 'gesture',
          screen_name: screen?.activityName,
          view_name: properties?.viewNameUpdated || properties?.viewName,
          view_type: properties?.viewType,
          element_id: properties?.idString,
          ...( ( isEvent || isSmartEvent || isScreenEvent ) ? {
            // eslint-disable-next-line no-nested-ternary
            type_of_event: isSmartEvent ? 'nocode' : isScreenEvent ? 'screenvisit' : name === 'UI Freeze' ? 'predefined' : 'custom',
          } : {} )
        }
      } ) )
    }
  }, [ collapseActiveKey, sessionid, isEvent, isSmartEvent, properties, screen, name, dispatch, isScreenEvent  ] )

  const extraCollapseBtn = (key) => (
    <span
      aria-hidden='true'
      onClick={() => handleCollapseBtnClick( key ) }
    >
      <SidebarCaretIcon />
    </span>
  );
  const handleRewind = useCallback(() => {
    onRewind(time);
  }, [onRewind, time]);

  const handleCreateEventBtn = useCallback( () => {
    setCurrentAction( {
      ...action,
      screenName: screen?.activityName,
      props: action?.params || action?.properties
    } )
    setCurrentScreen( screen )
    setManagePopupOpen( true )
  }, [setCurrentAction, action, setCurrentScreen, screen, setManagePopupOpen] )

  const handleEditEventBtn = useCallback(() => {
    setCurrentAction({
      ...action,
      props: properties || params,
    });
    setCurrentScreen(screen);
    if( isScreenEvent ) {
      setScreenEventModalOpen(true)
    } else {
      setManagePopupOpen(true);
    }
  }, [setCurrentAction, action, properties, params, setCurrentScreen, screen, isScreenEvent, setScreenEventModalOpen, setManagePopupOpen]);

  const handleClick = useCallback( () => {
    dispatch( trackPageViews( null, {
      eventName: 'wa_activity_click_on_bar_element',
      track_type: 'event',
      eventProperty: {
        session_id: sessionid, 
        clicked_element: ( isEvent || isSmartEvent || isScreenEvent ) ? 'event' : 'gesture',
      }
    } ) )
  }, [ dispatch, isEvent, isSmartEvent, sessionid, isScreenEvent ] )

  const handleItemClick = useCallback( () => {
    handleRewind()
    setSelectedScreenName( screen?.activityName )
  }, [ handleRewind, setSelectedScreenName, screen ] )

  return (
    <>
      <li
        key={gestureIndex}
        className={classNames(
          'gesture-box',
          {
            active,
          },
          { 'event-box': isEvent },
          {
            'ui-freeze-box': isEvent && name === 'UI Freeze',
          },
          { 'rage-box': isRage },
          {
            'old-sdk-box': !newSdk && isEvent,
          },
          {
            'no-code-box': noCodeEventsFeatureFlag && params,
          }
        )}
        aria-hidden="true"
      >
        <Collapse
          accordion
          activeKey={[collapseActiveKey]}
          expandIconPosition={['end']}
          ghost
        >
          <Panel
            showArrow={false}
            key={collapseKey}
            extra={extraCollapseBtn(collapseKey)}
            className='activity-header-wrap'
            onClick={ handleClick }
            header={
                <div>
                  <ul aria-hidden="true" onClick={ handleItemClick }>
                    <li className="gesture-time">{getActivityDisplayTime(time)}</li>
                    <li className={classNames(
                      'gesture-icon',
                      {'rage-icon': isRage && ( noCodeEventsFeatureFlag ? isSmartEvent : true ) }
                    )}>
                      <GesturePack
                        name={ identifyEventName(name, isRage, isEvent, ( isSmartEvent && noCodeEventsFeatureFlag ), (isScreenEvent && noCodeEventsFeatureFlag) ) }
                      />
                    </li>
                    <CustomLiWrap className="gesture-name" width={ `${ containerWidth - ( noCodeEventsFeatureFlag ? 133 : 100 ) }` }>
                      <GesturePopover
                        isEvent={isEvent}
                        isGesture={isGesture}
                        isScreenEvent={isScreenEvent}
                        isSmartEvent={isSmartEvent}
                        properties={properties}
                        params={params}
                        name={name}
                        newSdk={newSdk}
                      />
                    </CustomLiWrap>
                  </ul>
                  { displayAddEventBtn && !isSmartEvent && (
                    <AddEventWrapper>
                      <Tooltip title="Create event" align={ { offset: [ 0, 8 ] } } overlayStyle={ { pointerEvents: 'none' } } >
                        <button type="button" onClick={ handleCreateEventBtn } className='add-event-btn'>
                          <IconPlus />
                        </button>
                      </Tooltip>
                    </AddEventWrapper>
                  ) }
                  {
                    (isSmartEvent || isScreenEvent) && parentType !== 'shareSession' && (
                      <AddEventWrapper>
                        <Tooltip title="Edit event" align={ { offset: [ 0, 8 ] } } overlayStyle={ { pointerEvents: 'none' } } >
                          <button type="button" onClick={ handleEditEventBtn } className='add-event-btn'>
                            <IconMinus />
                          </button>
                        </Tooltip>
                      </AddEventWrapper>
                    ) 
                  }
                </div>
            }
          >
            <NewGestureCollapseContent
              action={action}
              eventName={name}
              isEvent={isEvent}
              newSdk={newSdk}
              handleCreateEventBtn={ handleCreateEventBtn }
              displayAddEventBtn={ displayAddEventBtn }
              screen={ screen }
            />
          </Panel>
        </Collapse>
      </li>
    </>
  );
});

const ScreenActionsTimeline = (props) => {
  const { containerWidth, action, gestureIndex, onRewind, currentGestures, screen } = props;
  const { isRageTapsGroup, rageGestures, time } = action;
  const initialRageTime = rageGestures ? rageGestures[0].time : '';
  const [rageCollapseActiveKey, setRageCollapseActiveKey] = useState('');
  const rageCollapseKey = useMemo(
    () => `${gestureIndex}-${initialRageTime}-${time}`,
    [gestureIndex, initialRageTime, time]
  );
  const extraRageCollapseBtn = (key) => (
    <span
      aria-hidden='true'
      onClick={() => {
        const recentKey = rageCollapseActiveKey === key ? '' : key;
        setRageCollapseActiveKey(recentKey);
      }}
    >
      <SidebarCaretIconWrap><SidebarCaretIcon /></SidebarCaretIconWrap>
    </span>
  );
  return (
    <>
      {isRageTapsGroup ?
        <CollapseWrapper
          accordion
          expandIconPosition={['end']}
          activeKey={[rageCollapseActiveKey]}
          ghost
        >
          <Panel
            showArrow={false}
            key={rageCollapseKey}
            extra={extraRageCollapseBtn(rageCollapseKey)}
            header={
              <>
                <ActivityTimeWrap>{getActivityDisplayTime(rageGestures[0].time)}</ActivityTimeWrap>
                <GroupedGestureWrap>
                  <RageIcon />
                  <span>Rage behavior ({rageGestures.length} gestures)</span>
                </GroupedGestureWrap>
              </>
            }>
            <>
              {rageGestures?.map((rageGesture, index) => {
                const rageGestureActive = currentGestures.has(rageGesture);
                return <GestureBox
                  active={rageGestureActive}
                  action={rageGesture}
                  containerWidth={containerWidth}
                  gestureIndex={gestureIndex + index + 1}
                  onRewind={onRewind}
                  screen={ screen}
                />
              })}
            </>
          </Panel>
        </CollapseWrapper>
        : <GestureBox
            active={currentGestures.has(action)}
            action={action}
            containerWidth={containerWidth}
            gestureIndex={gestureIndex} // gesture index to be looked upon 
            onRewind={onRewind} 
            screen={ screen }
          />
        }    
    </>
  );
};
export default memo(ScreenActionsTimeline);