import timeLineRandomColor from 'components/common/timeLineRandomColor';
import {
  getActivityDisplayTime,
  mapAppLogsWithScreen,
} from 'components/shared/Sessions/Video/utils';
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useWorker } from '@koale/useworker';
import {
  useSessionTimeLine,
  useSessionSidebar,
} from 'components/shared/Sessions/Context';
import { useDispatch, useSelector } from 'react-redux';
import { Skeleton } from 'antd';
import { debounce } from 'lodash';

import { useSessionAppLogs } from 'components/features/sessions/hooks/useSessionDetail';
import { trackPageViews } from 'redux/actions/trackingReport';
import { fetchPlanHatApi } from 'redux/actions/common';
import LogContent from './LogContent';
import LogFilter from './LogFilter';
import {
  AppLogWrapper,
  LogHeader,
  LogHeaderTitle,
  LogWrapper,
} from './styles/AppLogStyles';
import AppLogInfo from './AppLogInfo';


const valueObj = {
  d: 'Debug',
  e: 'Error',
  f: 'Fault',
  i: 'Info',
  u: 'Undefined',
  v: 'Verbose',
  w: 'Warning',
};

const AppLogs = () => {
  const dispatch = useDispatch();
  const { sessionDetail, sessionLogs, rewind } = useSessionTimeLine();
  const { selectedTab } = useSessionSidebar();
  const {
    urlReducer: { sessionid, shareSessionKey, appId },
  } = useSelector((state) => state);
  const {
    device: { platform },
  } = sessionDetail || {};
  const screenTimeLine = sessionDetail?.screenTimeline?.activities;
  const [initialResult, setInitialResult] = useState([]);
  const [logFilter, setLogFilter] = useState([]);
  const [searchText, setSearchText] = useState('');
  const [sortWorker] = useWorker(mapAppLogsWithScreen);

  const runSort = useCallback(async () => {
    const data = await sortWorker(screenTimeLine, sessionLogs); // non-blocking UI
    setInitialResult(data);
  }, [screenTimeLine, sessionLogs, sortWorker]);

  const reqBody = useMemo(
    () => ({
      appid: appId,
      sessionid,
    }),
    [appId, sessionid]
  );

  const { isLoading, isRefetching } = useSessionAppLogs(reqBody);

  const resultLogs = useMemo(
    () =>
      initialResult.map((item) => {
        const temp = { ...item };
        const escapedSearchText = searchText?.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const regex1 = new RegExp(escapedSearchText);
        if (searchText?.length) {
          temp.logs = item?.logs.filter(
            (value) =>
              searchText?.length && regex1.test(value.message?.toLowerCase())
          );
        }
        if (logFilter.length) {
          temp.logs = temp?.logs.filter(
            (value) => logFilter?.length && logFilter?.includes(value.level)
          );
        }
        return temp;
      }),
    [logFilter, initialResult, searchText]
  );

  const resultLogsCount = useMemo(
    () =>
      resultLogs.reduce(
        (previousValue, currentValue) =>
          previousValue + currentValue?.logs?.length,
        0
      ),
    [logFilter, searchText]
  );

  useEffect(() => {
    if (screenTimeLine && sessionLogs) {
      runSort();
    }
  }, [screenTimeLine, sessionLogs, runSort]);

  useEffect(() => {
    if (logFilter?.length < 1 && searchText === '') return;
    const filterVal = logFilter.map((item) => valueObj[item]);
    dispatch(
      trackPageViews(null, {
        eventName: 'filter_log',
        track_type: 'event',
        eventProperty: {
          sessionId: sessionid,
          filterDetails: { logFilter: filterVal, searchText },
          filteredLogCount: resultLogsCount,
        },
      })
    );

    dispatch(
      fetchPlanHatApi({
        action: 'Filter Log',
        info: {
          sessionId: sessionid,
          filterDetails: { logFilter: filterVal, searchText },
          filteredLogCount: resultLogsCount,
        },
      })
    );
  }, [resultLogsCount]);

  useEffect(() => {
    setLogFilter([]);
  }, [selectedTab, sessionid]);

  const changeHandler = (value) => {
    setSearchText(value?.length >= 3 ? value : '');
  };

  const handleRewind = (e, time) => {
    e.preventDefault();
    e.stopPropagation();
    rewind(time);
  };

  const debouncedChangeHandler = useCallback(debounce(changeHandler, 500), []);

  const handleLogFilter = (dataValue) => {
    setLogFilter(dataValue);
  };

  return (
    <>
      {initialResult?.length > 0 && !(isLoading || isRefetching) && (
        <LogFilter
          platform={platform}
          handleLogFilter={handleLogFilter}
          defaultFilter={logFilter}
          handleChange={debouncedChangeHandler}
        />
      )}
      <AppLogWrapper className="appLogWrapper" 
        size={initialResult?.length || 0}
        firstChildSize={initialResult[0]?.logs?.length || 0}
        secondChildSize={initialResult[1]?.logs?.length || 0}
      >
        <Skeleton
          loading={shareSessionKey ? false : isLoading || isRefetching}
          active
          paragraph={{ rows: 10 }}
        >
          {initialResult?.length > 0 && !isRefetching ? (
            resultLogs.map((value) => (
              <LogWrapper
                key={`${value?.activityName}-${value?.time}`}
                color={timeLineRandomColor(
                  value?.activityName ? value?.activityName.trim() : ''
                )}
                className='log-wrapper'
              >
                <LogHeader>
                  <LogHeaderTitle onClick={(e) => handleRewind(e, value?.time)}>
                    <strong>{getActivityDisplayTime(value?.time)}</strong>
                  </LogHeaderTitle>
                  <span>{value?.activityName}</span>
                </LogHeader>
                <LogContent logs={value?.logs} handleRewind={handleRewind} size={initialResult?.length} />
              </LogWrapper>
            ))
          ) : (
            <AppLogInfo platform={platform} isAppLogValid isAppLogRecorded={false} />
          )}
        </Skeleton>
      </AppLogWrapper>
    </>
  );
};

export default AppLogs;
