import React, { useMemo } from 'react';
import styled from 'styled-components';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { Tooltip } from 'antd';
import GesturePack from './GesturePack';
import ViewGesturePack from './ViewGesturePack';
import { gestureGenerateName } from './helpers';

const Name = styled.div`
  font-weight: 400 !important;
  i {
    font-style: italic !important;
    font-weight: 500;
  }
`

const GesturePopover = ({ isEvent, properties, params, name: nameProps, newSdk, isGesture, isSmartEvent, isScreenEvent }) => {
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()

  const gestureType = params?.gestureType || nameProps
  const name = properties?.viewNameUpdated || properties?.viewName || params?.viewName
  const viewType = params?.viewType || properties?.viewType
  const generatedName = useMemo( () => gestureGenerateName( gestureType, viewType, noCodeEventsFeatureFlag, name ), [ gestureType, name, viewType, noCodeEventsFeatureFlag ] )
  
  const generatedNameStr = useMemo( () => {
    if ( gestureType && viewType && noCodeEventsFeatureFlag ) {
      return `${ gestureType } - ${ (name && name !== "UnknownView") ? `${ name } ` : '' } ${ viewType && viewType !== "unknown" ? viewType : '' }`
    }
    return null
  }, [ gestureType, name, viewType, noCodeEventsFeatureFlag ] )

  const renderName = useMemo( () => {
    if ( noCodeEventsFeatureFlag && isGesture  ) {
      return <Name className="gesture-text">{ generatedName }</Name>
    }
    
    if ( isSmartEvent ) {
      return (
        <Tooltip 
            title={ `Original name: ${ generatedNameStr }` } 
            overlayClassName='tooltip-gesture-text'
            placement='bottomLeft'
            align={ { offset: [ 15, -5 ] } }
          >
            <Name className="gesture-text">
              <b>
                { nameProps }
              </b>
            </Name>
          </Tooltip>
      )
    } 
    
    return <div className="gesture-text">{ generatedName }</div>
  }, [noCodeEventsFeatureFlag, isGesture, isSmartEvent, generatedName, generatedNameStr, nameProps] )

  return (
    <>
      {newSdk && !isEvent && properties && <div className='icon-box'>
        <ViewGesturePack gesture={properties?.viewTypeId || ''} />
      </div>}
      { (!newSdk || !properties) && !isEvent && (
        <div className='icon-box'>
          <GesturePack name="generic" />
        </div>
      ) }
      { renderName  }
    </>
  )
}

export default GesturePopover;