/* eslint-disable react/jsx-props-no-spreading */
import React, { memo, useState, useMemo, useCallback } from 'react';
import { useSelector } from 'react-redux';
import { convertGetTime } from 'Utils/helpers/commonUtils';
import { SidebarCaretIcon } from 'components/svg_files';
import ScreenTimeline from './ScreenTimeline';
import { StyledCollapse } from './SessionDetailSideBarStyled';
import { getActivityDisplayTime } from '../../Video/utils';

const SkipBanner = ({ engagementTime, len, handleClick, viewTime }) => (
  <a href="#!" onClick={handleClick} className="skipped-header">
    <span className="name">
      {`${viewTime} Skipped ${len || 1} screen${len ? 's' : ''}`}
      <span className="caret-button">
        <SidebarCaretIcon />
      </span>
    </span>
    <span>{engagementTime}</span>
  </a>
);

const TimeLineWithMultiSkip = memo((props) => {
  const [visibleSkippedScreen, toggleSkippedScreen] = useState(false);
  const { screenList, ...restProps } = props;
  const sumOfViewTime = useMemo(
    () =>
      screenList.reduce(
        (acc, currentEl) => acc + (currentEl.endTime - currentEl.time),
        0
      ),
    [screenList],
    []
  );
  const totalSkippedEngagementTime = useMemo(
    () => convertGetTime({ durationInSecs: sumOfViewTime, roundFalse: false }),
    [sumOfViewTime]
  );
  const handleClick = useCallback(
    (e) => {
      e.preventDefault();
      toggleSkippedScreen(!visibleSkippedScreen);
    },
    [visibleSkippedScreen]
  );
  return (
    <StyledCollapse visibleSkippedScreen={visibleSkippedScreen}>
      <SkipBanner
        viewTime={getActivityDisplayTime(screenList[0]['time'])}
        len={screenList.length}
        engagementTime={totalSkippedEngagementTime}
        handleClick={handleClick}
      />
      {screenList.map((screenElement, elEventIndex) => {
        const viewtime = screenElement.endTime - screenElement.time;
        return (
          <ScreenTimeline
            // eslint-disable-next-line react/no-array-index-key
            key={screenElement.activityName + elEventIndex}
            eventIndex={elEventIndex}
            screen={screenElement}
            engagementTime={
              viewtime < 60
                ? `${Math.round(viewtime)} sec`
                : convertGetTime({
                    durationInSecs: viewtime,
                    roundFalse: false,
                  })
            }
            isSkippedScreenActivity
            disabled
            visibleSkippedScreen={visibleSkippedScreen}
            {...restProps}
          />
        );
      })}
    </StyledCollapse>
  );
});

const TimeLineWithSkip = memo((props) => {
  const [visibleSkippedScreen, toggleSkippedScreen] = useState(false);
  const {
    isSkippedScreenActivity,
    engagementTime,
    screen: { time } = {},
  } = props;
  const {
    screenTimelineReducer: { selectedScreens = [] },
  } = useSelector((state) => state);
  const handleClick = useCallback(
    (e) => {
      e.preventDefault();
      toggleSkippedScreen(!visibleSkippedScreen);
    },
    [visibleSkippedScreen]
  );
  return (
    <StyledCollapse visibleSkippedScreen={visibleSkippedScreen}>
      {isSkippedScreenActivity && selectedScreens.length && (
        <SkipBanner
          viewTime={getActivityDisplayTime(time)}
          handleClick={handleClick}
          engagementTime={engagementTime}
        />
      )}
      <ScreenTimeline visibleSkippedScreen={visibleSkippedScreen} {...props} />
    </StyledCollapse>
  );
});
export { TimeLineWithMultiSkip, TimeLineWithSkip };
