/* eslint-disable no-nested-ternary */
import React, { memo, useCallback, useMemo } from 'react';
import { isObject, isEmpty, map } from 'lodash';
import { RootStateOrAny, useDispatch, useSelector } from 'react-redux';
import ButtonNew from 'components/common/ButtonNew';
import IconNocodeSettings from 'public/static/icon-no-code-settings.svg';
import IconSession from 'public/static/icon-session-blue.svg';
import IconAnalyze from 'public/static/icon-analyze.svg';
import { getActionType } from 'Utils/helpers/SessionUtils';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { IAction, ISessionScreen } from 'types/sessionTypes';
import { trackPageViews } from 'redux/actions/trackingReport';
import { BottomWrapper, ContentWrapper } from './styles';
import { ManageEventWrapper, TopButtonWrapper } from './NewGestureCollapseContent';
import { useSessionVideoControlls } from '../../Context';

interface ScreenEventContentProps {
  action: IAction;
  activityName: string;
  screen: ISessionScreen;
  isScreenEventCreated?: boolean;
}

const ScreenEventContent: React.FC<ScreenEventContentProps> = (props) => {

  const dispatch = useDispatch();
  const { action, activityName, screen, isScreenEventCreated } = props;
  const { params, name } = action;

  const { currentAppReducer, urlReducer, screenRenamedList } = useSelector(
    (state: RootStateOrAny) => state
  );

  const renamedScreenName = useMemo(() => screenRenamedList[activityName] || activityName, [activityName, screenRenamedList]);
  
  const { setShowDashboardTemplate, setScreenEventModalOpen, setCurrentScreen, setCurrentAction } =
    useNoCodeEventsContext();

  const { _id: appId, orgId } = currentAppReducer;

  const isSharedSession = useMemo(
    () => urlReducer?.parentType === 'shareSession',
    [urlReducer?.parentType]
  );
  const constructedURL = useMemo(() => {
    const urlParam = {
      o: 'in',
      v: [name],
      tb: 'no_code_event',
    };
    const queryParams = `nce_name=${encodeURIComponent(JSON.stringify(urlParam))}`;
    const url = `/app/${appId}/sessions/list/1?${queryParams}`;

    return url;
  }, [appId, name])

  const handleWatchSessions = useCallback(() => {
    window?.open(constructedURL, '_blank');
  }, [constructedURL]);

  const { isScreenEvent } = getActionType(action);

  const isScreenEventEditMode = useMemo(
    () => isScreenEvent && isScreenEventCreated,
    [isScreenEvent, isScreenEventCreated]
  );

  const changeKey = (key: string) => {
    if (key === 'screenName') {
      return 'Original screen name';
    }
    return key;
  };

  const handleCreateSmartEvent = useCallback(() => {
    setCurrentScreen(screen);
    setScreenEventModalOpen(true);
  }, [screen, setCurrentScreen, setScreenEventModalOpen]);

  const { videoElemRef } = useSessionVideoControlls()

  const handleAnalyzeEvent = useCallback(() => {
    setCurrentAction({
      ...action,
      props: params
    });
    videoElemRef?.current?.pause()
    setCurrentScreen(screen)
    setShowDashboardTemplate(true)
  }, [setCurrentAction, action, params, videoElemRef, setCurrentScreen, screen, setShowDashboardTemplate]);

  const handleManageEventClick = useCallback(() => {
    dispatch(
      trackPageViews(null, {
        eventName: 'wa_manage_smart_events_redirect',
        track_type: 'event',
        eventProperty: {
          screen_name: renamedScreenName,
          original_screen_name: activityName,
          type_of_event: 'screenvisit',
        },
      })
    );
  }, [activityName, dispatch, renamedScreenName]);

  return (
    <ContentWrapper className="expanded-content">
      <div className="pop-height-wrap">
        <div className="event-param-name">
          <div className="event-key-title">Screen name:</div>
          <div>{renamedScreenName}</div>
        </div>
        {isObject(params) && !isEmpty(params) ? (
          map(params as object, (val, key) => {
            if (key !== 'rule')
              return (
                <div className="event-param-name" key={key}>
                  <div className="event-key-title">{changeKey(key)}:</div>
                  <div>{val}</div>
                </div>
              );
              return null;
          })
        ) : (
          <p className="no-eventparam-message">No properties sent</p>
        )}
      </div>
      {isSharedSession ? null : isScreenEventEditMode ? (
        <ManageEventWrapper>
        <TopButtonWrapper>
          <ButtonNew variant="ghost" onClick={handleWatchSessions}>
            <IconSession />
            Watch sessions
          </ButtonNew>
          <ButtonNew onClick={handleAnalyzeEvent}>
            <IconAnalyze />
            Analyze event
          </ButtonNew>
        </TopButtonWrapper>
        <a
          href={`/settings/app/${orgId}/${appId}/smart_events`}
          target="_blank"
          rel="noreferrer"
        >
          <ButtonNew variant="outline" onClick={handleManageEventClick}>
            <IconNocodeSettings />
            Manage Smart events
          </ButtonNew>
        </a>
      </ManageEventWrapper>
      ) : (
        <BottomWrapper>
          <ButtonNew width="medium" onClick={handleCreateSmartEvent}>
            Create event
          </ButtonNew>
        </BottomWrapper>
      )}
    </ContentWrapper>
  );
};

export default memo(ScreenEventContent);
