
import React from 'react';
import { useSelector } from 'react-redux';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import TimelineScreenDropdown from './TimelineScreenDropdown'
import TimelineScreenDropdownOld from './TimelineScreenDropdownOld'
import EventGestureTimelineDropdown from './EventGestureTimelineDropdown';
import EventGestureTimelineDropdownOld from './EventGestureTimelineDropdownOld';

const TimeLineFilterContainer = ({
  screenDropdownVisible,
  screenDropdownToggler,
  uploadedOn
}) => {
  const {
    urlReducer: {
      parentType
    },
  } = useSelector((state) => state);

  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()

  return (
    <div className={`screen-timeline-search ${parentType === 'heatmapsList' ? 'remove-screen-search' : ''}`}>
      { noCodeEventsFeatureFlag ? (
        <>
          <EventGestureTimelineDropdown uploadedOn={uploadedOn} />
          <TimelineScreenDropdown
            screenDropdownVisible={screenDropdownVisible}
            screenDropdownToggler={screenDropdownToggler}
            uploadedOn={uploadedOn}
          />
        </>
      ) : (
        <>
          <EventGestureTimelineDropdownOld uploadedOn={uploadedOn} />
          <TimelineScreenDropdownOld
            screenDropdownVisible={screenDropdownVisible}
            screenDropdownToggler={screenDropdownToggler}
            uploadedOn={uploadedOn}
          />
        </>
      ) }
    </div>
  );
};

export default TimeLineFilterContainer;
