import React, { memo, useCallback, useEffect, useMemo, useRef } from 'react';
import { Skeleton } from 'antd';
import classNames from 'classnames';
import timeLineRandomColor, { timeLineSequentialColor } from 'components/common/timeLineRandomColor';
import { useQueryClient } from 'react-query';
import { useDispatch, useSelector } from 'react-redux';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { ScreenTimelineStyled } from './SessionDetailSideBarStyled';
import ScreenActionsTimeline from '../Gestures/ScreenActionsTimeline';
import ScreenCollapseContent from '../Gestures/ScreenCollapseContent';
import { useScreenLayoutContext, useSessionSidebar } from '../../Context';

const ScreenTimeline = ({
  screen,
  active,
  onRewind,
  eventIndex,
  sessionDetail,
  currentGestures,
  // selectedFields,
  selectedGestureFields,
  selectedEventFields,
  selectedSmartEventFields,
  engagementTime,
  disabled,
  isSkippedScreenActivity,
  visibleSkippedScreen,
  uploadedOn,
}) => {
  const dispatch = useDispatch();
  const { setSelectedScreenName } = useSessionSidebar()
  const {
    urlReducer: { parentType, sessionid, secondarysessionid, shareSessionKey, appId },
    screenRenamedList,
  } = useSelector((state) => state);

  const { time, activityName, actions = [] } = screen;
  const { _id: detailSessionId } = sessionDetail;
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()
  const { getScreenLayoutData } = useScreenLayoutContext()

  const queryClient = useQueryClient();
  const sessionId = parentType === 'aiSessionsList' ? secondarysessionid : sessionid;
  const sessionEventQueryKey = useMemo(() => ['sessionEvents', {
      appid: appId,
      sessionId,
      uploadedon: uploadedOn,
    }], [appId, sessionId, uploadedOn]);
  const sessionNocodeEventsQueryKey = useMemo(() => ['sessionNocodeEvents', {
      appid: appId,
      sessionId,
      uploadedon: uploadedOn,
    }], [appId, sessionId, uploadedOn]);

  const sessionEvents = queryClient.getQueryData(sessionEventQueryKey);
  const sessionNocodeEvents = queryClient.getQueryData(sessionNocodeEventsQueryKey);

  const { aiSessionFeatureAllowed: aiSessionsEnabled } = useRestrictionContext() || {}
  const isAISessionPage = parentType === 'aiSessionsList' || parentType === 'aiSessionsDetail'
  const hasAIAnalyzedBanner =  !!sessionDetail?.sessionanalyzedbyai && !!aiSessionsEnabled && !!isAISessionPage;

  const topOffsetFromParent = useMemo(() => {
    if (parentType === 'heatmapsList') {
      return 160;
    }
    if (parentType === 'issues') {
      return 890;
    }
    return hasAIAnalyzedBanner ? 230 : 110;
  }, [hasAIAnalyzedBanner, parentType])

  const topOffset = topOffsetFromParent;
  const handleScreenRewind = useCallback(() => {
    onRewind(time + 0.001);
  }, [onRewind, time]);
  const handleGestureRewind = useCallback(
    (gestureTime) => {
      onRewind(gestureTime);
    },
    [onRewind]
  );
  const handleHeaderClick = useCallback(() => {
    setSelectedScreenName( activityName )
    handleScreenRewind();
    dispatch(
      trackPageViews(null, {
        eventName: 'wa_activity_click_on_bar_element',
        track_type: 'event',
        eventProperty: {
          session_id: sessionId,
          clicked_element: 'screen',
        },
      })
    );
  }, [sessionId, handleScreenRewind, dispatch, activityName, setSelectedScreenName]);
  const containerRef = useRef();
  useEffect(() => {
    if (active) {
      const container = containerRef.current;

      if (container) {
        const wrapper = container.closest('.event-wrapper');
        if (!wrapper) {
          return;
        }

        wrapper.scrollTo({
          behavior: 'smooth',
          top: container.offsetTop - topOffset,
        });
      }
    }
  }, [active]);

  const displayActions = React.useMemo(
    () =>
    actions.filter((action) => {
        const { name, type } = action;
        if (type === 'gesture') return selectedGestureFields[name];
        if (type === 'sdk_event') {
          if(sessionEvents && Object.keys(selectedEventFields || {}).length === 0) {
            return null;
          }
          return Object.keys(selectedEventFields || {}).length === 0 ? name : selectedEventFields[name];
        };
        if(sessionNocodeEvents && Object.keys(selectedSmartEventFields || {}).length === 0) {
          return null;
        }
        return Object.keys(selectedSmartEventFields || {}).length === 0 ? name : selectedSmartEventFields[name];
      }),
    [actions, selectedEventFields, selectedGestureFields, selectedSmartEventFields, sessionEvents, sessionNocodeEvents]
  );

  return (
    <ScreenTimelineStyled
      isSkippedScreenActivity={isSkippedScreenActivity}
      visibleSkippedScreen={visibleSkippedScreen}
      shareSessionKey={shareSessionKey}
      activityNameLength={
        (screenRenamedList[activityName] || activityName).length
      }
    >
      <div
        className={classNames('screen-timeline-display', {
          'screen-timeline-overlay': isSkippedScreenActivity,
        })}
        data-intercom-target={`${activityName} ${eventIndex}`}
      >
        <Skeleton
          loading={shareSessionKey ? false : sessionId !== detailSessionId}
          active
          paragraph={{ rows: 6 }}
        >
          <div
            ref={containerRef}
            className={classNames('event-item', `event-item-${eventIndex}`, {
              active,
              disabled,
            })}
            key={time + eventIndex}
            style={{
              borderLeft: `1px solid #F0F0FF`,
              borderRight: `1px solid #F0F0FF`,
              borderBottom: `1px solid #F0F0FF`,
              borderTop: `2px solid ${ getScreenLayoutData(parentType).isSequentialTimelineColor ?
                timeLineSequentialColor(eventIndex) :
                timeLineRandomColor(
                activityName ? activityName.trim() : ''
              )}`,
            }}
          >
            <ScreenCollapseContent
               screen={screen}
               eventIndex={eventIndex}
               active={active}
               handleHeaderClick={handleHeaderClick}
               time={time}
               activityName={activityName}
               isSkippedScreenActivity={isSkippedScreenActivity}
               engagementTime={engagementTime}
               onRewind={onRewind}
               noCodeEventsFeatureFlag={noCodeEventsFeatureFlag} />
            <div className="item-body" id={`gesture-body-${eventIndex}`}>
              <ul>
                {displayActions.length > 0 ? (
                  displayActions.map((action, gestureIndex) => (
                    <ScreenActionsTimeline
                      // eslint-disable-next-line react/no-array-index-key
                      key={gestureIndex}
                      action={action}
                      gestureIndex={gestureIndex}
                      onRewind={handleGestureRewind}
                      currentGestures={currentGestures}
                      containerWidth={
                        containerRef?.current?.getBoundingClientRect()?.width
                      }
                      screen={screen}
                    />
                  ))
                ) : (
                  <li className="no-interaction">No user interaction</li>
                )}
              </ul>
            </div>
          </div>
        </Skeleton>
      </div>
    </ScreenTimelineStyled>
  );
};

export default memo(ScreenTimeline);
