import React, { useCallback, useRef } from 'react';
import { Select } from 'antd';
import {
  FilterWrapper,
  SelectWrapper,
  SearchWrapper,
} from './styles/AppLogStyles';
import { mapLogsIcon } from './LogContent';

const { Option } = Select;

const valueObj = {
  d: 'Debug',
  e: 'Error',
  f: 'Fault',
  i: 'Info',
  u: 'Undefined',
  v: 'Verbose',
  w: 'Warning',
};

const filterList = [
  { value: 'd', display: 'Debug' },
  { value: 'e', display: 'Error' },
  { value: 'f', display: 'Fault' },
  { value: 'i', display: 'Info' },
  { value: 'u', display: 'Undefined' },
  { value: 'v', display: 'Verbose' },
  { value: 'w', display: 'Warning' },
];

const LogFilter = ({
  platform,
  handleLogFilter,
  defaultFilter,
  handleChange,
}) => {
  const containerRef = useRef();
  const handleGetContainer = useCallback(
    () => containerRef.current,
    [containerRef]
  );

  const findSelected = (selectedItem) => valueObj[selectedItem];

  const selectedFilter = defaultFilter.map(findSelected);
  return (
    <FilterWrapper ref={containerRef}>
      {platform === 1 ? (
        <SelectWrapper
          clearIcon
          showSearch={false}
          mode="multiple"
          value={defaultFilter}
          placeholder="Select to filter logs"
          maxTagCount={selectedFilter.join('')?.length > 11 ? 1 : 2}
          maxTagTextLength={5}
          onChange={handleLogFilter}
          getPopupContainer={handleGetContainer}
        >
          {filterList &&
            filterList.map((item) => (
              <Option value={item.value}>
                {' '}
                {mapLogsIcon[item.value]}
                {item.display}
              </Option>
            ))}
        </SelectWrapper>
      ) : null}
      <SearchWrapper
        placeholder="Type to filter logs ..."
        onChange={(e) => handleChange(e.target.value)}
      />
    </FilterWrapper>
  );
};

export default LogFilter;
