import React, { memo } from 'react'
import NocodeIcon from 'public/static/icon-no-code.svg';
import { 
  GestureSingleTap,
    GestureDoubleTap, 
    GestureSwipeUp, 
    GestureSwipeDown, 
    GestureSwipeLeft, 
    GestureSwipeRight, 
    GestureLongPress,
    GestureZoomIn,
    GestureZoomOut,
    GestureUnknown,
    GestureOrientationChange,
    GestureTrail,
    IconEvent,
    GestureGeneric,
    IconRage,
    IconUIFreeze,
    GestureSingleRage,
    GestureDoubleRage,
    SmartEventIcon,
} from './GestureIcon';

const GesturePack = ({ name }) => {
  const gestureIcon = (() => {
    const gestureName = name.toLowerCase();
    switch(gestureName) {
      case 'single tap':
        return <GestureSingleTap />;
      case 'double tap':
        return <GestureDoubleTap />;
      case 'swipe up':
        return <GestureSwipeUp />;
      case 'swipe down':
        return <GestureSwipeDown />;
      case 'swipe left':
        return <GestureSwipeLeft />;
      case 'swipe right':
        return <GestureSwipeRight />;
      case 'long press':
        return <GestureLongPress />;
      case 'zoom in':
        return <GestureZoomIn />;
      case 'zoom out':
        return <GestureZoomOut />;
      case 'unknown':
        return <GestureUnknown />;
      case 'orientation change':
        return <GestureOrientationChange />;
      case 'trail':
        return <GestureTrail />
      case 'rage':
        return <IconRage />;
      case 'single rage':
        return <GestureSingleRage />;
      case 'double rage':
        return <GestureDoubleRage />;
      case 'event':
        return <IconEvent />;
      case 'no-code event':
        return <SmartEventIcon data-element='no-code' />;
      case 'generic':
        return <GestureGeneric />;
      case 'ui freeze':
        return <IconUIFreeze />;
      case 'smart_screenvisit_event':
        return <SmartEventIcon />;
      default:
        return null;
    }
  })(); 
    return (
      <span>
        {gestureIcon}
      </span>
    )
}
export default memo(GesturePack);