import React, { memo, useState, useEffect, useRef, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Menu, Dropdown, Checkbox, Button, Badge, Tooltip } from 'antd';
import styled from 'styled-components';
import { DebounceInput } from 'react-debounce-input';
import { QuickFilterSVG } from 'components/svg_files';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';
import {
  setScreenTimeLineEvents,
  setScreenTimeLineGestures,
  setAllEvents,
  setSessionEventTriggered,
} from 'redux/actions/video';
import {
  useSessionEvents,
  useSessionGestures,
  useShareSessionData,
} from 'components/features/sessions/hooks/useSessionDetail';
import { trackPageViews } from 'redux/actions/trackingReport';
import { getPopupContainer } from 'Utils/helpers/commonUtils';
import GesturePack from '../../Gestures/GesturePack';

export const MenuItemGroup = Menu.ItemGroup;
export const MenuItem = Menu.Item;
const DropdownHeaderStyled = styled.div`
  .ant-input {
    margin-bottom: 5px;
    border-radius: 4px;
  }
`
export const ScreenTimelineSearch = memo(({
    menuList,
    title,
    searchValue,
    type,
    selectedList,
    handleMenuClick,
    loadingEvents,
    loadingSharedEvents,

  }) => (
      <MenuItemGroup title={title} className="menu-item-group">
        {menuList.length ? (
          menuList.filter(x => x.name.toLowerCase().includes(searchValue)).map((item) =>
            <Menu.Item
              className={item.count === 0 ? 'timeline-options timeline-event-none' : 'timeline-options'}
              key={item.name + item.count}
            >
              <Checkbox
                className="check-option"
                checked={selectedList.map(v => v.name).includes(item.name)}
                onChange={(e) => handleMenuClick(e, item, type)}
                value={item.name}
                key={item.name}
              >
                <div className="check-option-title" >
                  <span className="check-option-name">
                    {type === 'gestures' && (<GesturePack name={item.name} />)}{' '}
                    {item.name}
                  </span>
                  <span className="check-option-count">{item.count}</span>
                </div>
              </Checkbox>
            </Menu.Item>
          )
        ) :  (
              <div className="no-event-message">
                {
                loadingEvents ||     loadingSharedEvents
                ? `loading ${type}...` : `No ${type} in this session`
                }
              </div>
        )}
      </MenuItemGroup>
));

const EventGestureTimelineDropdownOld = ({
  uploadedOn,
}) => {
  const {
      sessionDetailReducer: sessionDetail,
      screenTimelineReducer: screenFilteredData,
      urlReducer: urlQuery
  } = useSelector((state) => state);
  const {
    selectedEventField,
    selectedGestureField,
    allEvents,
    isEventTriggered,
  } = screenFilteredData;
  const inputRef = useRef();
  const dispatch = useDispatch();
  const [searchValue, setSearchValue] = useState('');
  const [eventList, setEventList] = useState([]);
  const [gestureList, setGestureList] = useState([]);
  const [eventVisible, setEventVisible] = useState(false);
  const [gestureVisible, setGestureVisible] = useState(false);
  const [checkAllEvents, setCheckAllEvents] = useState(false);
  const [checkAllGesture, setCheckAllGesture] = useState(false);
  const [toogleEvent, setToogleEvent] = useState(allEvents);

  const { sessionid, secondarysessionid, parentType , appId } = urlQuery;
  const { setSessionGestures, setSessionEvents , sessionGestures: sharedSessionGestures} = useSessionTimeLine();
  // const sessionId = sessionDetail.data?.['_id'];
  const shareKey = urlQuery.shareSessionKey;
  const sessionId =  parentType === 'aiSessionsList' ? secondarysessionid : sessionid

  const reqBody = useMemo(
    () => ({
      appid: appId,
      sessionid: sessionId,
      uploadedon: uploadedOn
    }),
    [appId, sessionId, uploadedOn]
  );

  const isSharedSession = useMemo(() => urlQuery?.parentType === 'shareSession', [urlQuery]);
  const { data: sessionGestures, refetch: refetchGestures, isLoading: loadingGestures } =
    useSessionGestures(reqBody, !isSharedSession);
  const { data: sessionEvents, isLoading: loadingEvents } =
    useSessionEvents(reqBody, eventVisible && !isSharedSession);

  const { data: sharedSessionEventsResponse, isLoading: loadingSharedEvents } =
    useShareSessionData(
      'event-details',
      '/sessions/get-event-details/',
      shareKey,
      eventVisible && isSharedSession
    );
  const sharedSessionEvents = useMemo(() => sharedSessionEventsResponse?.data?.data || [], [sharedSessionEventsResponse]);

  const gestureCount = sessionGestures?.length || 0;
  const eventCount = sessionEvents?.length || 0;
  const sessionDetailLoader = sessionDetail?.loader;
  const itemsChanged = useRef({
    changed: false,
    type: '',
  });

  useEffect(() => {
    if (sessionGestures && !isSharedSession) {
      setGestureList(sessionGestures?.data?.data || []);
      setSessionGestures(sessionGestures?.data?.data || []);
    }
  }, [isSharedSession, sessionGestures, setSessionGestures]);

  useEffect(() => {
    if (sessionEvents && !isSharedSession) {
      setEventList(sessionEvents?.data?.data || []);
      setSessionEvents(sessionEvents?.data?.data || []);
    }
    return () => {
      setSessionEvents([]);
    };
  }, [isSharedSession, sessionEvents, setSessionEvents]);

  useEffect(() => {
    if (isSharedSession && sharedSessionGestures) {
      setGestureList(sharedSessionGestures);
    }
  }, [isSharedSession, sharedSessionGestures]);

  useEffect(() => {
    if (
      isSharedSession &&
      sharedSessionEvents &&
      sharedSessionEvents.length > 0
    ) {
      setEventList(sharedSessionEvents);
    }
  }, [isSharedSession, sharedSessionEvents]);

  useEffect(() => {
    // NOTE: CX-1635
    if (!isSharedSession && sessionId) {
      refetchGestures();
    }
  }, [sessionId]);

  const doContainFieldName = (fields, name) => fields.some((field) => field.name === name);

  const handleMenuClick = async (e, { name, count }, selectedValue) => {
    itemsChanged.current = {
      changed: true,
      type: selectedValue,
    };
    e.preventDefault()
    if (selectedValue === 'events') {
      let newEventList = [];
      const containEvent = selectedEventField.map(v => v.name).indexOf(name) > -1
      if (containEvent)
        newEventList = selectedEventField.filter((value) => value.name !== name);
      else newEventList = [...selectedEventField, { name, count }];
      await dispatch(setScreenTimeLineEvents(newEventList));
      dispatch(trackPageViews(null, {
          eventName: 'filter_events',
          track_type: 'event',
          pageName: urlQuery?.parentType,
          eventProperty: {
            ...(urlQuery?.parentType === 'heatmapsList' && { screenname: urlQuery?.screenname }),
            ...(urlQuery?.parentType === 'heatmapsList' && { sessionid: sessionId }),
          }
        }));
    }
    if (selectedValue === 'gestures') {
      let newGestureList = [];
      const containGesture = selectedGestureField.map(v => v.name).indexOf(name) > -1
      if (containGesture)
        newGestureList = selectedGestureField.filter( (value) => value.name !== name );
      else newGestureList = [...selectedGestureField, { name, count }];
      await dispatch(setScreenTimeLineGestures(newGestureList));
      dispatch(trackPageViews(null, {
          eventName: 'filter_gestures',
          track_type: 'event',
          pageName: urlQuery?.parentType,
          eventProperty: {
            gestures: newGestureList,
            ...(urlQuery?.parentType === 'heatmapsList' && { screenname: urlQuery?.screenname }),
            ...(urlQuery?.parentType === 'heatmapsList' && { sessionid: sessionId }),
          }
        }))
    }
    dispatch(setSessionEventTriggered(true));
  };


  const removeDuplicates = (array, key) => {
    const lookup = new Set();
    return array.filter((obj) => !lookup.has(obj[key]) && lookup.add(obj[key]));
  };

  const handleSearch = (e) => setSearchValue(e.target.value.trim().toLowerCase());

  const handleSelectAll = async (e, value) => {
    if (e.target.checked) {
      if (value === 'events') {
        const allEventField = [...selectedEventField, ...eventList];
        const uniqueEvents = removeDuplicates(allEventField, 'name');
        const evenData = toogleEvent
          ? uniqueEvents
          : uniqueEvents.filter((event) => event.count !== 0);
        await dispatch(setScreenTimeLineEvents(evenData));
        dispatch(trackPageViews(null, {
          eventName: 'filter_events',
          track_type: 'event',
          pageName: urlQuery?.parentType,
          eventProperty: {
            ...(urlQuery?.parentType === 'heatmapsList' && { screenname: urlQuery?.screenname }),
            ...(urlQuery?.parentType === 'heatmapsList' && { sessionid: sessionId }),
          }
        }));
      }
      if (value === 'gestures') {
        const allGestureField = [...selectedGestureField, ...gestureList];
        await dispatch(
          setScreenTimeLineGestures(removeDuplicates(allGestureField, 'name'))
        );
        dispatch(trackPageViews(null, {
          eventName: 'filter_gestures',
          track_type: 'event',
          pageName: urlQuery?.parentType,
          eventProperty: {
            gestures: allGestureField,
            ...(urlQuery?.parentType === 'heatmapsList' && { screenname: urlQuery?.screenname }),
            ...(urlQuery?.parentType === 'heatmapsList' && { sessionid: sessionId }),
          }
        }));
      }
    } else {
      if (value === 'events') {
        const evenData = toogleEvent
          ? []
          : eventList.filter((event) => event.count === 0);
        await dispatch(setScreenTimeLineEvents(evenData));
      }
      if (value === 'gestures') {
        await dispatch(setScreenTimeLineGestures([]));
      }
    }
    setSearchValue('');
    dispatch(setSessionEventTriggered(true));
  };

  const handleToggle = (flag) => {
    setToogleEvent(flag);
    dispatch(setAllEvents(flag));
  };

  const title = (value) => (
    <DropdownHeaderStyled>
      {value === 'events' && (
        <DebounceInput
          value={searchValue}
          placeholder="Search"
          debounceTimeout={500}
          className="ant-input debounce-input"
          inputRef={inputRef}
          onChange={handleSearch}
        />
      )}
      {value === 'events' && (
        <span className="timeline-event-toggle">
          <Button
            className={toogleEvent && 'active-toggle-btn'}
            onClick={() => handleToggle(true)}
          >
            All events
          </Button>
          <Button
            className={!toogleEvent && 'active-toggle-btn'}
            onClick={() => handleToggle(false)}
          >
            In this session
          </Button>
        </span>
      )}
      <Checkbox
        checked={value === 'events' ? checkAllEvents : checkAllGesture}
        onClick={(e) => handleSelectAll(e, value)}
      >
        <span className="checkbox-span">
          {value === 'events' ? 'Events' : 'Gestures'}
        </span>
      </Checkbox>
    </DropdownHeaderStyled>
  );

  const getListItems = (list) => toogleEvent ? list : list.filter((item) => item.count !== 0);
  const filterMenu = (type) => (
    <Menu>
      <ScreenTimelineSearch
        key={type}
        type={type}
        menuList={type === 'events' ? getListItems(eventList) : gestureList}
        title={title(type)}
        searchValue={searchValue}
        selectedList={type === 'events' ? selectedEventField : selectedGestureField}
        handleMenuClick={handleMenuClick}
        loadingEvents={loadingEvents}
        loadingSharedEvents={loadingSharedEvents}
      />
    </Menu>
  );

  const handleEventVisibleChange = (flag) => {
    setEventVisible(flag);
    setSearchValue('');
  };

  const handleGestureVisibleChange = (flag) => {
    setGestureVisible(flag);
    setSearchValue('');
  };

  const checkAll = (selectedList, allList, type) => {
    let allListFiltered = [];
    if (type === 'events') {
      allListFiltered = !toogleEvent
        ? allList.filter((arr) => arr.count !== 0)
        : allList;
    } else allListFiltered = allList;
    return allListFiltered.length
      ? allListFiltered.every((v) =>
        selectedList.some((a) => a.name === v.name)
      )
      : true;
  };

  const getCheckedCount = (type) => {
    let count = 0;
    const actualList = type === 'events' ? eventList : gestureList;
    const selectedList = type === 'events' ? selectedEventField : selectedGestureField;
    actualList.forEach((al) => {
      if (doContainFieldName(selectedList, al.name)) {
        count += 1;
      }
    });
    return count;
  };

  useEffect(() => {
    if (sessionEvents && sessionGestures) {
      setEventList(sessionEvents?.data.data);
      setGestureList(sessionGestures?.data.data);
    }
  }, [sessionId, toogleEvent, sessionEvents, sessionGestures]);

  useEffect(() => {
    if (eventList?.length) {
      dispatch(
        setScreenTimeLineEvents(
          !isEventTriggered
            ? eventList
            : selectedEventField
        )
      );
    }

    return () => {
      setScreenTimeLineEvents([]);
    }

  }, [eventList, sessionEvents]);

  useEffect(() => {
    const getFilterType = (type) => {
      switch (type) {
        case 'events':
          return 'Events';
        case 'gestures':
          return 'Gestures';
        default:
          return '';
      }
    }

    if(!eventVisible || !gestureVisible){
      if(itemsChanged.current.changed){
        dispatch(trackPageViews(null, {
          eventName: 'wa_localized_filter_applied', 
          eventProperty: {
            filterName: getFilterType(itemsChanged.current.type),
          }
        }))
        itemsChanged.current = {
          changed: false,
          type: '',
        };
      }
    }
  }, [eventVisible, gestureVisible])

  useEffect(() => {
    if (!gestureList.length) return;
    dispatch(
      setScreenTimeLineGestures(
        !isEventTriggered && selectedGestureField.length === 0
          ? gestureList
          : selectedGestureField
      )
    );
  }, [gestureList]);
  
  useEffect(() => {
    setCheckAllEvents(checkAll(selectedEventField, eventList, 'events'));
  }, [selectedEventField.length, toogleEvent, eventList]);

  useEffect(() => {
    setCheckAllGesture(checkAll(selectedGestureField, gestureList, 'gestures'));
  }, [selectedGestureField.length, gestureList]);

  useEffect(() => {
    if (inputRef.current && eventVisible) {
      setTimeout(() => {
        inputRef.current.focus();
      }, 1000);
    }
  }, [eventVisible, toogleEvent]);

  return (
    <>
      <Dropdown
        visible={eventVisible}
        disabled={sessionDetailLoader}
        trigger={['click']}
        onVisibleChange={handleEventVisibleChange}
        overlay={filterMenu('events')}
        overlayClassName="screen-timeline-search-dropdown"
        getPopupContainer={getPopupContainer}
      >
        <Tooltip title="Select events that should be shown on the timeline.">
          <Button className={ getCheckedCount('events') < eventCount ? 'filter-applied' : '' } data-intercom-target="Events dropdown">
            <QuickFilterSVG /> Events{' '}
            {getCheckedCount('events') < eventCount && (
              <Badge showZero count={getCheckedCount('events')} />
            )}
          </Button>
        </Tooltip>
      </Dropdown>
      <Dropdown
        disabled={sessionDetailLoader}
        visible={gestureVisible}
        trigger={['click']}
        onVisibleChange={handleGestureVisibleChange}
        overlay={filterMenu('gestures')}
        overlayClassName="screen-timeline-search-dropdown"
        getPopupContainer={getPopupContainer}
      >
        <Tooltip title="Select gestures that should be shown on the timeline.">
          <Button loading={loadingGestures} className={ getCheckedCount('gesture') < gestureCount ? 'filter-applied' : '' } >
            <QuickFilterSVG /> Gestures{' '}
            {getCheckedCount('gesture') < gestureCount && (
              <Badge showZero count={getCheckedCount('gesture')} />
            )}
          </Button>
        </Tooltip>
      </Dropdown>
    </>
  )
}

export default EventGestureTimelineDropdownOld
