import React, { useEffect, useRef, useState } from 'react';
import { Button } from 'antd';
import { Mention, MentionsInput } from 'react-mentions';
import { useMutation, useQueryClient } from 'react-query';
import { useDispatch, useSelector } from 'react-redux';

import {
  secondsToTime,
  timeFormatRegex,
  timeFormatToSecond,
} from 'Utils/helpers/commonUtils';
import { axiosInstance } from 'services/globalInstance';
import { useTeamList } from 'components/features/sessions/hooks/useSessionDetail';
import { trackPageViews } from 'redux/actions/trackingReport';

import NoteList from './SessionNoteList';
import {
  useSessionTimeLine,
  useSessionVideoControlls,
  useSessionSidebar,
  useSessionVideoContext,
} from '../../Context';

// Css is defined here because we need send on react mentions
const defaultStyle = {
  control: {
    backgroundColor: '#fff',
    fontSize: 12,
    fontWeight: 'normal',
  },
  '&multiLine': {
    control: {
      fontFamily: 'Roboto',
      minHeight: 120,
    },
    highlighter: {
      padding: 9,
      border: '1px solid transparent',
      // textRendering: 'geometricPrecision'
    },
    input: {
      padding: 9,
      border: '1px solid silver',
      // textRendering: 'geometricPrecision'
    },
  },
};
let container;

const SessionNoteAddForm = (props) => {
  const dispatch = useDispatch();
  const noteInput = useRef(null);
  const { appId: appid, parentType } = useSelector(state => state.urlReducer)
  const { sessionDetail } = useSessionTimeLine();
  const { timeRef } = useSessionVideoControlls();
  const { selectedTab, noteTime, setNoteTime } = useSessionSidebar();
  const { isPlaying } = useSessionVideoContext();
  const [defaultNoteText, setDefaultNoteText] = useState('');
  const [errorMessage, setErrorMessage] = useState(false);
  const [displayNote, setDisplayNote] = useState(false);
  const [testValue, setTestValue] = useState([]);
  const [users, setUsers] = useState([]);
  const { redirectToVideo } = props;
  const { _id: sessionId, appId, recTime, time } = sessionDetail || {};
  const [timeFormat, setTimeFormat] = useState([]);
  const queryClient = useQueryClient();
  const appIdCopy = appId || appid
  const videoDuration = recTime && timeFormatToSecond(recTime);
  const { current } = timeRef;
  const sessionUploadedDateTime  = time?.sessionUploadedDateTime

  const teamReqBody = React.useMemo(() => appIdCopy, [appId]);

  const teamQueryKey = React.useMemo(() => ['team-user', appId], [appId]);

  const { data: teamList } = useTeamList(teamQueryKey, teamReqBody);

  useEffect(() => {
    if (teamList) {
      const usersList = teamList?.data?.data?.map((user, index) => ({
        id: index,
        email: user.email,
        display: user.name,
      }));
      setUsers(usersList);
    }
  }, [teamList, appId]);

  const { mutate: saveSessionNote, isLoading: saveNoteLoading } = useMutation(
    (body) =>
      axiosInstance.post(
        `${process.env.PYTHON_API_URL}/notes/session/create`,
        body,
        {
          withCredentials: true,
          credentials: 'include',
        }
      ),
    {
      onSuccess: () => {
        setDefaultNoteText('');
        setTimeFormat([]);
        setNoteTime(null);
        return queryClient.invalidateQueries(['session-note', sessionId]);
      },
      onMutate: () => {
        const sessionKey = parentType === 'aiSessionsList' ? 'aiSessionItems' : 'sessionItems'
        const sessionBodyKey = parentType === 'aiSessionsList' ? 'aiSessionsListReqBody' : 'sessionsListReqBody'
        let sessionBodyKeyVal = ''
        try {
          sessionBodyKeyVal = JSON.parse(localStorage.getItem(sessionBodyKey))
        } catch (err) {
          // silent fail
        }
        const sessionQueryKey = [sessionKey, sessionBodyKeyVal]
        queryClient.cancelQueries(sessionQueryKey);
        const previousValue = queryClient.getQueryData(sessionQueryKey);
        previousValue &&
          queryClient.setQueryData(sessionQueryKey, (old) => {
            const newBody = old.data.data.body.map((el) => {
              if (el.sessionid === sessionId) {
                return {
                  ...el,
                  sessionNotesCount: el.sessionNotesCount + 1,
                };
              }
              return el;
            });
            return {
              ...old,
              data: {
                ...old.data,
                data: {
                  ...old.data.data,
                  body: newBody,
                },
              },
            };
          });
        return previousValue;
      },
    }
  );

  const commonToChangeValue = (noteData) => {
    let content = noteData;
    users.map((user) => {
      content = content.replaceAll(
        `@[${user.display}](${user.id})`,
        `${user.display}`
      );
    });
    const blocks = content.split(' ');
    const matchString = blocks.map((block) => {
      let content = block;
      if (block.match(timeFormatRegex)) {
        const matchArray = block.match(timeFormatRegex);
        matchArray.length &&
          matchArray.map((matchTime) => {
            content = content.replaceAll(`@[${matchTime}](abc)`, matchTime);
          });
        return content;
      }
      return `${block}`;
    });
    return matchString.join(' ');
  };

  const handleSubmit = () => {
    const isValidNote = defaultNoteText.trim();
    if (isValidNote.length && !errorMessage) {
      const values = {};
      let content = defaultNoteText;
      users.map((user) => {
        content = content.replaceAll(
          `[${user.display}](${user.id})`,
          `${user.email}`
        );
      });
      const blocks = content.split(' ');
      const matchString = blocks.map((block) => {
        let content = block;
        if (block.match(timeFormatRegex)) {
          const matchArray = block.match(timeFormatRegex);
          matchArray.length &&
            matchArray.map((matchTime) => {
              content = content.replaceAll(`@[${matchTime}](abc)`, matchTime);
            });
          return content;
        }
        return `${block}`;
      });
      values.body = matchString.join(' ');
      values.appid = appId;
      values.sessionid = sessionId;
      values.uploadedon = sessionUploadedDateTime;
      values.isaisession = parentType === 'aiSessionsList';
      dispatch(trackPageViews(null, {
          eventName: 'add_note',
          track_type: 'event',
          pageName: parentType,
          eventProperty: { sessionid: sessionId, note: matchString.join(' ') }
      }))
      saveSessionNote(values);
    } else {
      setErrorMessage(true);
      setDefaultNoteText(isValidNote);
    }
  };

  const handleChange = (e) => {
    const { value } = e.target;
    let replaceValue = value;
    timeFormat.length &&
      timeFormat.map((time) => {
        replaceValue = replaceValue.replaceAll(`@[${time}](abc)`, `${time}`);
      });
    const blocks = replaceValue.split(' ');
    setTestValue([]);
    const matchString = blocks.map((block) => {
      let content = block;
      if (block.match(timeFormatRegex)) {
        const matchArray = block.match(timeFormatRegex);
        setTestValue(matchArray);
        matchArray.length &&
          matchArray.map((matchTime) => {
            content = content.replaceAll(`@[${matchTime}](abc)`, matchTime);
            content = content.replaceAll(matchTime, `@[${matchTime}](abc)`);
          });
        return content;
      }
      return `${block}`;
    });
    const valueEvent = matchString.join(' ');
    setDefaultNoteText(valueEvent);
    const displayText = commonToChangeValue(valueEvent);
    value.length && setErrorMessage(false);
    displayText.length >= 1000 && setErrorMessage(true);
  };

  const handleDefaultTimeOnNote = () => {
    const time =
      current <= 0
        ? ''
        : current >= videoDuration
        ? `${recTime}`
        : ` ${secondsToTime(current)} `;
    isPlaying
      ? setDefaultNoteText(
          `${defaultNoteText}${' '} ${secondsToTime(current)} `
        )
      : setDefaultNoteText(`${defaultNoteText}${time}`);
    return isPlaying
      ? `${defaultNoteText}${secondsToTime(current)} `
      : `${defaultNoteText}${time}`;
  };

  useEffect(() => {
    if (noteInput.current) {
      setDefaultNoteText('');
      setErrorMessage(false);
    }
    setTimeFormat([]);

   const timer = setTimeout(() => {
      noteInput?.current && noteInput?.current.focus();
    }, 1000);
    return () => {
      clearTimeout(timer)
    }
  }, [noteInput, displayNote, selectedTab, sessionId]);

  useEffect(() => {
    if (current && selectedTab === 'notes') {
      (async () => {
        const note = await handleDefaultTimeOnNote();
        setDefaultNoteText(noteTime ? note : '');
      })();
      setTimeout(() => {
        noteInput?.current && noteInput?.current.focus();
      }, 1000);
    }
  }, [noteTime]);

  useEffect(() => {
    if (testValue.length) {
      const array3 = timeFormat.concat(testValue);
      setTimeFormat([...new Set(array3)]);
    }
  }, [testValue]);

  useEffect(() => {
    setDisplayNote(true);
  }, [appId]);
  return (
    <div className="session-note-tab">
      {displayNote && (
        <div
          ref={(el) => {
            container = el;
          }}
        >
          <NoteList
            users={users}
            defaultStyle={defaultStyle}
            redirectToVideo={redirectToVideo}
            sessionDetail={sessionDetail}
          />
          <MentionsInput
            inputRef={noteInput}
            className={`mention-input ${
              errorMessage ? 'validation-message' : ''
            }`}
            value={defaultNoteText}
            onChange={handleChange}
            placeholder="Write your note"
            maxLength={1000}
            style={defaultStyle}
            suggestionsPortalHost={container}
            forceSuggestionsAboveCursor
          >
            <Mention
              trigger="@"
              data={users}
              appendSpaceOnAdd
              className="mention-inner-highlight"
            />
          </MentionsInput>
          <div className="mention-outer">
            <Button
              onClick={() => handleSubmit()}
              disabled={defaultNoteText?.length >= 1000}
              className="save-btn note-save-btn"
              loading={saveNoteLoading}
            >
              Save note
            </Button>
            {errorMessage && !defaultNoteText ? (
              <div className="has-error">Note can’t be empty.</div>
            ) : (
              ''
            )}
            {errorMessage &&
            defaultNoteText &&
            defaultNoteText.length >= 1000 ? (
              <div className="has-error">
                Reached max limit of 1000 characters.
              </div>
            ) : (
              ''
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default SessionNoteAddForm;
