/* eslint-disable arrow-body-style */
import React, { useCallback, useEffect, useMemo } from 'react';
import { Tooltip, Button, Dropdown, Badge, Menu } from 'antd';
import { useSelector, useDispatch } from 'react-redux';
import classNames from 'classnames';
import { uniq } from 'lodash';
import { QuickFilterSVG } from 'components/svg_files';
import {
  useSessionScreenList,
  useAppScreenList,
} from 'components/features/sessions/hooks/useSessionDetailsSidebar';
import {
  setSelectedScreens,
  setLastMessageByKey,
  setScreenList,
} from 'redux/actions/video'
import { fetchPlanHatApi } from 'redux/actions/common';
import { useShareSessionData } from 'components/features/sessions/hooks/useSessionDetail';
import { getPopupContainer } from 'Utils/helpers/commonUtils';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { DropdownStyled } from './DropdownStyled'
import ScreenMenuItems from './ScreenMenuItems'

const screenUncheckedMessage = 'You have unselected all the screen in this session from the screens filter. Please select at least 1 screen from this session to play the video.'
const findCommonElements = (arr1, arr2) => arr1.some(item => arr2.includes(item))
const TimelineScreenDropdown = ({
  screenDropdownVisible,
  screenDropdownToggler,
  uploadedOn
}) => {
  const dispatch = useDispatch()
  const { sessionDetailScreens } = useSessionTimeLine()

  const { 
    screenTimelineReducer: { selectedScreens = [], screenList },
    urlReducer: { appId: appid, sessionid, shareSessionKey },
    appFilter: { dateSegment,}
  } =
    useSelector((state) => state);

  const { sessionDetail } = useSessionTimeLine();
  const newScreensFilter = useFeatureFlag( 'new-screens-filter' ) 

  const { data: rawSessionScreenData, refetch: refetchSessionScreen, isLoading: sessionScreenLoading } =
    shareSessionKey
      ? useShareSessionData(
        'screens-details',
        '/sessions/get-all-screens/',
        shareSessionKey
      )
      : useSessionScreenList({
        sessionid,
        appid,
        uploadedon: uploadedOn
      });

  const sessionScreenData = useMemo(() => ({
      data: {
        data: ( sessionDetail?.screenTimeline?.activities || [] )
        .reduce( ( acc, { activityName, endTime, time } ) => {
          const viewtime = endTime - time;
          const existing = acc.find( ( { screenName } ) => screenName === activityName )
          if ( existing ) {
            existing.duration += viewtime
            return acc
          }
          acc.push({
              screenName: activityName,
              duration: viewtime,
          } )
          return acc
        }, [] )
      }
    }), [sessionDetail])


  const {
    data: { data: { data: appScreens = [] } = {} } = {},
    refetch,
    isLoading: loading,
  } = useAppScreenList(
    {
      appid,
      attribute: newScreensFilter ? 'screen_name' : 'session_screen_list',
      date_range: dateSegment,
      dropdownLimit: 501,
      filter: [],
      search: '',
      table: 'session'
    },
    { enabled: !shareSessionKey }
  );

  const sessionScreensList = useMemo(
    () =>
      sessionScreenData
        ? sessionScreenData.data?.data
          .filter((v, index) => v.screenName !== 'Launch' || index !== 0)
          .sort((a, b) => b.duration - a.duration)
        : [],
    [sessionScreenData]
  );

  const sessionScreens = useMemo(
    () => sessionScreensList.map((v) => v.screenName),
    [sessionScreensList]
  )

  const showCountFlag = useMemo(
    () => selectedScreens.length !== screenList.length,
    [selectedScreens, screenList]
  );

  const onVisibleChange = useCallback( (visible) => {
    screenDropdownToggler(visible);
    if (visible) dispatch(fetchPlanHatApi({ action: 'View all user screens from session details page' }))
  }, [screenDropdownToggler, dispatch]);

  useEffect(() => {
    if (!shareSessionKey) refetch();
  }, [appid]);

  useEffect(() => {
    if (!shareSessionKey && sessionid) refetchSessionScreen();
  }, [sessionid]);

  useEffect(() => {
    if (!shareSessionKey && appScreens?.length && sessionScreens?.length) {
      let newData = []
      if(screenList.length)
      sessionScreens.map(v => {
        if(!screenList.includes(v)) {
          newData = [...newData, v]
        }
      })
      const newScreenList = screenList?.length ? uniq([...screenList, ...sessionScreens]) : uniq([...appScreens, ...sessionScreens])
      const newselected = selectedScreens.length ? uniq([...selectedScreens, ...newData]) : newScreenList
      dispatch(setScreenList(newScreenList));
      dispatch(setSelectedScreens(newselected));
    }
  }, [appScreens, sessionScreens]);

   useEffect(() => {
    if (!shareSessionKey && selectedScreens.length && sessionScreens.length)
      dispatch(setLastMessageByKey({ flag: !findCommonElements(sessionScreens, selectedScreens), message: !findCommonElements(sessionScreens, selectedScreens) ? screenUncheckedMessage : '' }))
  }, [sessionScreens, selectedScreens])

  useEffect(() => {
    if (sessionScreens.length && shareSessionKey) {
      dispatch(setScreenList(sessionScreens));
      dispatch(setSelectedScreens(sessionScreens));
    }
  }, [sessionScreens]);

  const menu = useMemo( () => (
    <Menu>
      <ScreenMenuItems
        key="screen-menu-Items"
        screenDropdownVisible={screenDropdownVisible}
        sessionScreensList={sessionScreensList}
        sessionScreens={sessionScreens}
        screenDropdownToggler={screenDropdownToggler}
        onVisibleChange={ onVisibleChange }
      />
    </Menu>
  ), [ screenDropdownVisible, sessionScreensList, sessionScreens, screenDropdownToggler, onVisibleChange ] )
  return (
    <DropdownStyled isFullscreen={Boolean(document.mozFullScreenElement)}>
      <Dropdown
        visible={screenDropdownVisible}
        trigger={['click']}
        onVisibleChange={onVisibleChange}
        overlay={menu}
        overlayClassName="screen-timeline-search-dropdown-restyled"
        placement="bottomRight"
        key="timeline-screen-dropdown"
        getPopupContainer={getPopupContainer}
        align={ { offset: [ 0, 8 ] } }
      >
        <Tooltip title="Select screens that should be shown on the timeline.">
          <Button
            className={classNames('screen-btn', { 'filter-applied': showCountFlag })}
            loading={loading || sessionScreenLoading}
          >
            <QuickFilterSVG /> Screens{' '}
            {showCountFlag && <Badge count={selectedScreens.length} />}
          </Button>
        </Tooltip>
      </Dropdown>
    </DropdownStyled>
  );
};

export default TimelineScreenDropdown;
